        // возвращает результат запроса в виде Словаря строк, строка = именновынный массив, ключи = первый столбец.
        public Dictionary< object ,Dictionary<object, object>> get_wms_sql_result_dictionary2(string strSQL)
        {
            OracleCommand ora_com = new OracleCommand();
            ora_com.Connection = get_wms_connection();
            ora_com.CommandText = strSQL;
            OracleDataReader ora_read = ora_com.ExecuteReader();

            Dictionary<object, Dictionary<object, object>> ret = new Dictionary<object, Dictionary<object, object>>();
            while (ora_read.Read())
            {
                Dictionary<object, object> row1 = new Dictionary<object, object>();
                for (int i = 0; i < ora_read.FieldCount; i++)
                {
                    row1[ora_read.GetName(i)] = ora_read.GetValue(i);
                }
                ret.Add(ora_read.GetValue(0), row1);
            }
            return ret;
        }

