        public string double2sql_ora(double dt)
        {
            return dt.ToString().Replace(',', '.');
        }

        public string date2sql(DateTime dt)
        {
            return "#" + dt.Month + "/" + dt.Day + "/" + dt.Year + "#";
        }

        public string date2sql_ora(DateTime dt)
        {


            return "'" + dt.Day + "." + dt.Month + "." + dt.Year + "'";

        }

        public DateTime date2strip_time(DateTime dt)
        {
            return Convert.ToDateTime("" + dt.Day + "." + dt.Month + "." + dt.Year + "");
        }

        public string datetime2sql_ora(DateTime dt)
        {
            return "'" + dt.Day + "." + dt.Month + "." + dt.Year + " " + dt.Second + ":" + dt.Minute + ":" + dt.Hour + "'";
        }

        public string datetime2sql_ora(DateTime dt, DateTime dt2)
        {
            return " TO_DATE( '" + dt.Day + "." + dt.Month + "." + dt.Year + " " +dt2.Hour + ":" + dt2.Minute + ":" + dt2.Second  + "' , 'dd.mm.YYYY HH24:MI:SS' ) ";
            
        }

