        private void dataGridView_prihod_CellEnter(object sender, DataGridViewCellEventArgs e)
        {
            if ((dataGridView_prihod).CurrentRow == null)
                return;

            DataGridViewRow dr = (dataGridView_prihod).CurrentRow;
            string order_id = obj2str(dr.Cells[6].Value);
            long condition = Convert.ToInt64(dr.Cells[5].Value);

            if (condition == 0) // Редактируется
            {
                Закрыть.Enabled = true;
                Разместить.Enabled = false;
                Откатить.Enabled = false;
                Сторнировать_приход.Enabled = false;
            }

            if (condition == 1) // закрыта
            {
                Закрыть.Enabled = false;
                Разместить.Enabled = true;
                Откатить.Enabled = true;
                Сторнировать_приход.Enabled = false;
            }

            if (condition == 2) // Размещена
            {
                Закрыть.Enabled = false;
                Разместить.Enabled = false;
                Откатить.Enabled = false;
                Сторнировать_приход.Enabled = has_right("STORNO_PRIHOD");
            }

            if (condition == 3) // Сторнирована
            {
                Закрыть.Enabled = false;
                Разместить.Enabled = false;
                Откатить.Enabled = false;
                Сторнировать_приход.Enabled = false;
            }



            if (order_id != "")
            {
                string strSQL = " SELECT RR.ARTICUL , RR.COUNT1 , RR.PRICE , RR.EXPIRY_DATE , RR.ID , " +
                    " RR.kolpal ,  RRL_GET_MOD_INFO( MOD_ID ) , DEFECT_PERC , GTD , SERTIF , rrl_articuls.NAME " + // ,
               "  FROM rabaev.RRL_PRIHOD_NAKLAD_ROWS RR , rrl_articuls where ORDID = " + order_id + " and  " +
               " rrl_articuls.acticul=RR.ARTICUL ";
                fill_view_MINI_WMS(dataGridView5, strSQL, 11);

                // Заполняем информацию по данному приходу
                strSQL = " select DOCK ,  PRIORITY1 , CHECKING_TIME , PLANNING_ACCEPT_TIME , PROOVED , WARE_ID from rrl_prihod_naklad "+
                    " where  ID = " + order_id + " ";



                List< Dictionary<object, object > > r1= get_wms_sql_result_dictionary3(strSQL);
                PRIHOD_DOCK.Text = r1[0]["DOCK"].ToString();
                PRIHOD_PRICE_CONTROL.Text = r1[0]["CHECKING_TIME"].ToString();
                PRIHOD_PLAN_TIME.Text = r1[0]["PLANNING_ACCEPT_TIME"].ToString();
                change_ware_id.Text = r1[0]["WARE_ID"].ToString();

                switch (r1[0]["PRIORITY1"].ToString() )
                {
                    case "10":
                         PRIHOD_PRIORITY.Text ="В ОЧЕРЕДИ";
                        break;
                    case "30":
                         PRIHOD_PRIORITY.Text ="НЕ СПЛАНИРОВАН";
                        break;
                    case "20":
                         PRIHOD_PRIORITY.Text ="ОТКЛОНЕН";
                        break;
                    case "5":
                        PRIHOD_PRIORITY.Text = "ПРИОРИТЕТ";
                        break;
                    default:
                        PRIHOD_PRIORITY.Text ="В ОЧЕРЕДИ";
                        break;
                }

                //НЕ СПЛАНИРОВАН - 30
                //ОТКЛОНЕН - 20
                //В ОЧЕРЕДИ  - 10
                //ПРИОРИТЕТ - 5



                
  /*        DOCK                  VARCHAR2(15 BYTE),
            INTEGER                 DEFAULT 0,
            DATE,
            DATE,
            PRIHOD_DOCK
            PRIHOD_PRIORITY
            PRIHOD_PRICE_CONTROL
            PRIHOD_PLAN_TIME
                */

            }
            else
            {
                dataGridView5.Rows.Clear();
            }

            #region ОБНОВЛЕНИЕ СТРОК ПАЛЛЕТ

            if (dataGridView_prihod.CurrentRow.Cells[0].Value == null)
            {
                dataGrid_pallets.Rows.Clear();
                return;
            }

            if (dataGridView_prihod.CurrentRow != null)
            {
                if (dataGridView_prihod.CurrentRow.Cells[6].Value != null)
                {
                    string h_order_id = dataGridView_prihod.CurrentRow.Cells[6].Value.ToString();
                    string strSQL7 = " select RR.UID_PALLET  , RR.ARTICUL , RR.UNIT_COUNT  , " +
                    " RR.PRIHOD_NAKLAD_ID , RR.EXPIRY_DATE , " +
                    " RR.CREATION_DATE , RABAEV.RRL_INFO_PALLET_RESTS(UID_PALLET) , " +
                    " int2bool(PRINTED) , RR.CREATION_DATE , AA.Name , " +
                    " WEIGHT_TN , WEIGHT_BRUTTO , RRL_GET_MOD_INFO( MOD_ID ) , DEFECT_PERC ,  COUNT_KOR , AA.type_w , MOD_ID  " +
                    " from  RABAEV.RRL_PALLETS RR , rrl_articuls AA " +
                     " where PRIHOD_NAKLAD_ID=" + h_order_id + " and RR.ARTICUL=AA.acticul " +
                     " order by  AA.Name , RR.CREATION_DATE   ";
                    if (Показывать_остатки.Checked==false)
                    {
                        strSQL7 = " select RR.UID_PALLET  , RR.ARTICUL , RR.UNIT_COUNT  , " +
                        " RR.PRIHOD_NAKLAD_ID , RR.EXPIRY_DATE , " +
                        " RR.CREATION_DATE , '' , " +
                        " int2bool(PRINTED) , RR.CREATION_DATE , AA.Name , " +
                        " WEIGHT_TN , WEIGHT_BRUTTO , RRL_GET_MOD_INFO( MOD_ID ) , DEFECT_PERC ,  COUNT_KOR , AA.type_w , MOD_ID  " +
                        " from  RABAEV.RRL_PALLETS RR , rrl_articuls AA " +
                         " where PRIHOD_NAKLAD_ID=" + h_order_id + " and RR.ARTICUL=AA.acticul " +
                         " order by  AA.Name , RR.CREATION_DATE   ";
                    }


                    fill_view_MINI_WMS(dataGrid_pallets, strSQL7, 17);
                }
            }
            #endregion

        }

