        private void Закрыть_Click(object sender, EventArgs e)
        {  
            
            string veh = obj2str(dataGridView_prihod.CurrentRow.Cells[9].Value).Trim();
                if (veh == "")
                {
                    MessageBox.Show( "Укажите номер машины" );
                    return;
                }


            try
            {
                dataGridView_prihod.CurrentRow.Cells[5].Value = 1;
                int order_id = Convert.ToInt32(dataGridView_prihod.CurrentRow.Cells[6].Value.ToString());

                // ===========================================================
              

                if ( obj2int(CachedQuerySingle(" select control_logo_par from rrl_wares where id='" + wms_user.ware_id.ToString() + "' "))==1)
                {
                    // control_logo_par 
                    string strSQL = "  select  rs.ARTICUL , DIMKOR_X X , DIMKOR_Y Y , DIMKOR_Z Z , COUNT_SHT_IN_KOR ШТУК_В_КОР , "+
                        " BRUTTO_WEIGHT_OF_KOR   ВЕС_КОРОБКИ "+
                        " from  RABAEV.RRL_PRIHOD_NAKLAD_ROWS rs , RABAEV.RRL_ARTICULS art  " +
                        "  where ORDID=" + order_id + "  and art.ACTICUL = rs.ARTICUL and " +
                        " (( DIMKOR_X*DIMKOR_Y*DIMKOR_Z )=0  or  ( BRUTTO_WEIGHT_OF_KOR<=0  ) or (COUNT_SHT_IN_KOR <=0 ) ) ";

                    List<Dictionary<object, object>> res1 = get_wms_sql_result_dictionary3(strSQL);
                    if (res1.Count > 0)
                    {
                        ShowArray(res1 , "Исправьте неверные логопараметры у данных позиций.");
                        return;
                    }
                }

                OracleCommand ora_com = new OracleCommand();
                ora_com.Connection = get_wms_connection();

                ora_com.CommandText = "RRL_ACCEPT_ORDER2_3";
                ora_com.CommandType = CommandType.StoredProcedure;
                ora_com.Parameters.Add("order_id", OracleType.Int32).Value = order_id;
                ora_com.Parameters.Add("user_id1", OracleType.VarChar).Value = this.wms_user.user_id;

                ora_com.Parameters.Add("ret", OracleType.Int32).Direction = ParameterDirection.ReturnValue;

                int rowsAffected = ora_com.ExecuteNonQuery();

            }
            catch (Exception ex)
            {
                MessageBox.Show(" f37 " + ex.Message);
            }

            dataGridView_prihod_CellEnter(null, null);

        }

