        private bool has_right_to_print_pallet(string h_UID_PALLET, long CONDITION_PRINT)
        {
            bool to_print = true;
            // Если в настройках склада указано контролировать статус накладной перед печатью, то
            // Идем в бухгалтерскую базу, находим там накладную, выставленную на основании данного заказа, 
            // либо накладную  с указанным номером и смотрим лучший DOCSTATE 
            // Данные о номере СТ и накладной берем из накладной ВМС, которой принадлежит паллет.
            string ST_NUMBER = ""; string NAKLAD_NUMBER = "";
            OracleCommand ora_com26 = new OracleCommand();
            ora_com26.Connection = get_wms_connection();
            ora_com26.CommandText = " select ZAKAZ_NUMBER , SM_NAKLAD_NUMBER " +
                " from RABAEV.RRL_PALLETS PAL , RRL_PRIHOD_NAKLAD NAKL " +
                " where PAL.UID_PALLET='" + h_UID_PALLET + "'  " +
                " and  PAL.PRIHOD_NAKLAD_ID = NAKL.ID ";
            OracleDataReader ora_read26 = ora_com26.ExecuteReader();
            if (ora_read26.Read())
            {
                ST_NUMBER = ora_read26.GetValue(0).ToString();
                NAKLAD_NUMBER = ora_read26.GetValue(1).ToString();
                long stat_in_sm = SUPERMAG_NAKLAD_BEST_STATUS(ST_NUMBER, NAKLAD_NUMBER);
                if (CONDITION_PRINT <= stat_in_sm) // Если состояние накладной больще, чем в настройке склада,
                {// то печатать можно.
                    to_print = true;
                }
                else
                {
                    to_print = false;
                }
            }
            else
            {
                MessageBox.Show("Паллет '" + h_UID_PALLET + "' не имеет накладной");
                to_print = false;
            }
            return to_print;
        }

        private void button18_Click(object sender, EventArgs e)
        {

            long count_forbidden_2_print = 0;

            string strSQL2 = " select CONDITION_PRINT from RRL_WARES where ID=" + this.wms_user.ware_id.ToString() + " ";
            long CONDITION_PRINT = obj2int(get_wms_sql_result_single(strSQL2));

            foreach (DataGridViewRow dr in dataGrid_pallets.Rows)
            {
                try
                {
                    if (Convert.ToBoolean(dr.Cells[7].Value) == false)
                    {


                        PPage _page = new PPage();
                        string h_UID_PALLET = "";
                        if (dr != null)
                        {
                            h_UID_PALLET = dr.Cells[0].Value.ToString();
                        }
                        bool to_print = true;
                        if (CONDITION_PRINT > 0) // Если в настройках склада указано контролировать статус накладной перед печатью, то
                        { // Идем в бухгалтерскую базу, находим там накладную, выставленную на основании данного заказа, 
                            // либо накладную  с указанным номером и смотрим лучший DOCSTATE 
                            // Данные о номере СТ и накладной берем из накладной ВМС, которой принадлежит паллет.
                            to_print = has_right_to_print_pallet(h_UID_PALLET, CONDITION_PRINT);
                        }

                        if (to_print) // Если печатать разрешено.
                        {
                            _page = get_prihod_pallet_print_page(h_UID_PALLET, "");
                            PPages.Add(_page);
                            string strSQL = " update RABAEV.RRL_PALLETS set PRINTED=1 where UID_PALLET='" + h_UID_PALLET + "' ";
                            OracleCommand ora_com = new OracleCommand();
                            ora_com.Connection = get_wms_connection();
                            ora_com.CommandText = strSQL;
                            ora_com.ExecuteNonQuery();
                            dr.Cells[7].Value = true;
                        }
                        else {
                            count_forbidden_2_print++;
                        }
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show(ex.Message);
                }
            }

            if (PPages.Count < 1)
            {
                if (count_forbidden_2_print > 0)
                {
                    MessageBox.Show("По данному приходу не создано накладных в Супермаге. \n Обратитесь в отдел товарного учета. ");
                    return;
                }

                MessageBox.Show("Нет паллет для печати паспортов, либоо паспорта печетались раннее. \n Для того, чтобы распечатать паспорта второй раз уберите флажки 'печать' с паллет. ");
                return;
            }


            #region НАЧАЛО_ПЕЧАТИ

            PrintDocument pd = new PrintDocument();
            try
            {

                pd.DefaultPageSettings.Landscape = true;
                pd.PrintPage += new PrintPageEventHandler
                    (pd_PrintPage_SBOR);
                pd.Print();
            }
            catch (Exception ex)
            {
                MessageBox.Show(" f48 " + ex.Message);
            }

            #endregion







        }

