        private string decode_cell(string CELL)
        {
            return CELL.Replace('С', 'C').Replace('М', 'M').Replace('Б', 'B').Replace('Г', 'G').Replace('А', 'A').Replace('Д', 'D').Replace('В', 'V').Replace('Е', 'E').Replace('Л', 'L').Replace('О', 'O');
        }

        private string decode_cell(string CELL, long ware_id)
        {
            if (CELL == "----")
            {
                if (ware_id == 1) { CELL = "C----"; }
                if (ware_id == 2) { CELL = "M----"; }
                if (ware_id == 3) { CELL = "A----"; }
                if (ware_id == 4) { CELL = "B----"; }
                if (ware_id == 5) { CELL = "I----"; }

                if (ware_id == 6) { CELL = "O----"; }
                if (ware_id == 7) { CELL = "D----"; }
                if (ware_id == 8) { CELL = "V----"; }
                if (ware_id == 11) { CELL = "L----"; }
                if (ware_id == 5) { CELL = "E----"; }
            }

            return CELL.Replace('С', 'C').Replace('М', 'M').Replace('Б', 'B').Replace('Г', 'G').Replace('А', 'A').Replace('Д', 'D').Replace('В', 'V').Replace('Е', 'E').Replace('Л', 'L').Replace('О', 'O');
        }

        private void SyncCELL(string CELL, long ware_id)
        {
            OracleCommand ora_com9 = new OracleCommand();
            ora_com9.Connection = get_wms_connection();
            ora_com9.CommandText = " select ware_id from RABAEV.RRL_CELLS where CELL='" + CELL + "' ";

            long ware2id = Convert.ToInt32(ora_com9.ExecuteScalar());


            if (ware2id == 0)
            { // Создаем  ячейку
                string strSQL = " insert into RABAEV.RRL_CELLS (CELL , OTBOR , WARE_ID ) values ( '" + CELL + "' , 1 , " + ware_id.ToString() + " ) ";
                ora_com9.CommandText = strSQL;
                ora_com9.ExecuteNonQuery();


            }
            else
            {
                if (ware2id != ware_id)
                {
                    MessageBox.Show(" Ячейка " + CELL + " принадлежит другому складу. \n сейчас принадлежит складу № " + ware2id.ToString() + " \n попытка создать в  " + ware_id.ToString());
                }
            }

            ora_com9.Dispose();

        }

        private void Alert(string error_text)
        {
            OracleCommand ora_com9 = new OracleCommand();
            ora_com9.Connection = get_wms_connection();
            ora_com9.CommandText = " insert into RABAEV.RRL_ERROR_LOG ( ERROR , DATET , USER_ID ) values ( '" + error_text + "' , " + date2sql_ora(DateTime.Now) + " , '" + this.wms_user.user_id + "' ) ";

            ora_com9.ExecuteNonQuery();
            ora_com9.Dispose();
            //if(box)
            // MessageBox.Show( error_text );

        }


        private void SyncПорядокСборки(string articul1)
        {
            return;

            Dictionary<string, long> l_ПорядокКомплектации = new Dictionary<string, long>();
            Dictionary<string, long> l_РЦЕКомплект = new Dictionary<string, long>();

            string str4 = "";
            if (articul1 != "")
            {
                str4 = " and ( c.article='" + articul1 + "' ) ";
            }

            string strSQL = " select c.article, c.shortname, sp.propval РЦЕКомплект , sp1.propval Порядоккомплектации " +
            "  from supermag.smcard c, supermag.smcardproperties sp , supermag.smcardproperties sp1 " +
            " where c.article = sp.article " +
            " and sp.propid = 'User.RCComplect' " +
            " and sp1.propid = 'User.pcsort' " +
            " and c.article = sp1.article  " + str4;

            OracleConnection ora_conn = new OracleConnection();
            ora_conn.ConnectionString = SM_CONNECTION_STRING();
            ora_conn.Open();

            OracleCommand ora_com5 = new OracleCommand();
            ora_com5.Connection = get_wms_connection();

            OracleCommand ora_com = new OracleCommand();
            ora_com.Connection = ora_conn;
            ora_com.CommandText = strSQL;

            OracleDataReader ora_read = ora_com.ExecuteReader();
            while (ora_read.Read())
            {
                l_ПорядокКомплектации[obj2str(ora_read.GetValue(0))] = obj2int(ora_read.GetValue(3));
                l_РЦЕКомплект[obj2str(ora_read.GetValue(0))] = obj2int(ora_read.GetValue(2));
                string strSQL8 = " update RRL_ARTICULS set ORDER_OF_COMP=" +
                    obj2int(ora_read.GetValue(3)).ToString() +
                    "  , RCEComplect=" + obj2int(ora_read.GetValue(2)).ToString() +
