                ora_com5.CommandText = strSQL8;
                ora_com5.ExecuteNonQuery();

            }

        }

        private bool SyncCompileSQ(string art, long ware_id , OracleConnection connection_2_sm)
        {
            return true;
            OracleCommand ora_com = new OracleCommand();
            ora_com.Connection = connection_2_sm;
            ora_com.CommandText = " select   sp.propval  , sp2.propval " + 
            " from supermag.smcard c,  " + 
            " supermag.smcardproperties sp , " + 
            " supermag.smcardproperties sp2  " + 
            " where c.article = sp.article " + 
            " and c.article = sp2.article " +
            " and c.article ='" + art + "' " + 
            " and  sp.propid= 'User.RCComplect' " + 
            " and  sp2.propid= 'User.pcsort'  ";

            OracleDataReader ora_read = ora_com.ExecuteReader();
            if (ora_read.Read())
            {
                int SQ = obj2int32(ora_read.GetValue(0));
                int SQ_GROUP = obj2int32(ora_read.GetValue(1));
                if (SQ_GROUP <= 0) SQ_GROUP = 100;
                if (SQ > 0)
                {
                    Dictionary<string, object> vl = new Dictionary<string, object>();
                    vl["articul1"] = art;
                    vl["ware_id1"] = ware_id;
                    vl["SQ1"] = SQ;
                    vl["SQGROUP"] = SQ_GROUP;
                    wms_get_spfunction_value2("compl.update_seq", vl, OracleType.UInt32, 0);

                }
            }
            else {
                return false;
            }
            return true;
        }

        // Если артикул создан не успешно (непример нет ячейки), то возвращает  ложь.
        private bool SyncArticul(string art, long ware_id)
        {   // Синхронизация артикула =========================================================

            string ACTICUL = art;//   VARCHAR2(15 CHAR),
            long NORMA_UKLADKI = 0; // NUMBER                         NOT NULL,
            string CELL = "-----"; //  VARCHAR2(50 CHAR),
            string NAME = ""; // VARCHAR2(255 CHAR),
            string UNIT_TYPE = ""; // VARCHAR2(20 CHAR),
            string BARCODE_SHT = ""; // VARCHAR2(128 CHAR)             DEFAULT 777                   NOT NULL,
            string BARCODE_KOR = ""; // VARCHAR2(128 CHAR),
            string BARCODE_BL = ""; // VARCHAR2(128 CHAR),
            double WEIGHT_OF_KOR = 0; // NUMBER,
            long COUNT_IN_ROW = 0; //INTEGER,
            long ROWS_IN_PAL = 0; //INTEGER
            string old_cell = "----";
            bool sync_barcodes = false;

            if (ware_id == 0)
            {
                MessageBox.Show("Артикул '" + art + "' с нулевым складом не может быть синхронизован");
                return false;
            }


            #region  НЕ ОБНОВЛЯЕМ, ТОЛЬКО ВСТАВЛЯЕМ!!!
            OracleCommand ora_com = new OracleCommand();
            OracleConnection ora_conn = new OracleConnection();
            ora_conn.ConnectionString = MINI_WMS_CONNECTION_STRING();
