            }


            try
            {

                WEIGHT_OF_KOR = Convert.ToDouble(Вес_коробки);

                NORMA_UKLADKI = Convert.ToInt64(Количество_штук_в_коробке) *
                    Convert.ToInt64(Количество_рядов_в_паллете) *
                    Convert.ToInt64(Количество_мест_в_ряду);
