                COUNT_IN_ROW = Convert.ToInt64(Количество_мест_в_ряду);
                ROWS_IN_PAL = Convert.ToInt64(Количество_рядов_в_паллете);
            }
            catch (Exception ex)
            {
                Alert(" Не корректно заполнена карточка артикула " + art + ". Обратитесь в ОТУ. \n " + ex.Message);
                NORMA_UKLADKI = 10000;

                //return;
            }

            SyncCompileSQ(art, ware_id, ora_conn);
            ora_conn.Close();





            if (BARCODE_SHT == "")
            {
                BARCODE_SHT = "none";
            }
            if (BARCODE_KOR == "")
            {
                BARCODE_KOR = "none";
            }

            if (need_insert)
            {
                long type_w = 0;
                try
                {
                    type_w = obj2int(CachedQuerySingle(" select type_w from RABAEV.RRL_WARES where id=" + ware_id.ToString() + "  "));
                }
                catch { }

                strSQL = " insert into RABAEV.RRL_ARTICULS ( " +
                "  ACTICUL       , " +
                "  NORMA_UKLADKI  , " +
                "  CELL   , " +
                "  NAME   , " +
                "  UNIT_TYPE    , " +
                "  BARCODE_SHT   , " +
                "  BARCODE_KOR   , " +
                "  BARCODE_BL    , " +
                "  WEIGHT_OF_KOR , " +
                "  COUNT_IN_ROW   , " +
                "  ROWS_IN_PAL , COUNT_SHT_IN_KOR , COUNT_SHT_IN_BL , type_w " +
                " ) values ( " +
                " '" + ACTICUL + "' , " +
                " " + NORMA_UKLADKI + ", " +
                " '" + CELL + "', " +
                " '" + NAME.Replace("'", "") + "', " +
                " '" + UNIT_TYPE + "', " +
                " '" + BARCODE_SHT + "', " +
                " '" + BARCODE_KOR + "', " +
                " '" + BARCODE_BL + "', " +
                " " + WEIGHT_OF_KOR.ToString().Replace(',', '.') + ", " +
                " " + COUNT_IN_ROW + ", " +
                " " + ROWS_IN_PAL + " , " + Количество_штук_в_коробке.ToString().Replace(',', '.') + " , 1  , " +
                " " + type_w.ToString() + " " +
                " ) ";

                ExecuteOracleNonQuery(strSQL);

            }
            else
            {
                //ОБновление не действует!!!!
                
                string cell_update = "  CELL = '" + CELL + "' , ";
                string sht_in_kor = ", COUNT_SHT_IN_KOR= " + Количество_штук_в_коробке.ToString().Replace(',', '.') + "";
                if (update_cell_manually == 1)
                {
                    cell_update = "";
                    sht_in_kor = "";
                }


                NAME = NAME.Replace("'", "");
                string NAME3 = NAME.Replace("'", "");
                strSQL = " update RABAEV.RRL_ARTICULS set  " +
              "  NORMA_UKLADKI =" + NORMA_UKLADKI + " , " +
              cell_update+
