        public object wms_get_spfunction_value2(string spf, Dictionary<string , object> values ,
            OracleType return_type , int return_size )
        {
             // Dictionary<string , OracleType> types ,
            OracleCommand ora_com = new OracleCommand();
            ora_com.Connection = get_wms_connection();
            ora_com.CommandText = spf;
            ora_com.CommandType = CommandType.StoredProcedure;


            try
            {

                foreach (string key in values.Keys)
                {
                    OracleType tp = OracleType.VarChar;
                    Type tp2 = values[key].GetType();
                    switch (tp2.Name)
                    {
                        case "UInt16":
                            ora_com.Parameters.Add(key, OracleType.UInt16).Value = values[key];
                            break;
                        case "UInt32":
                            ora_com.Parameters.Add(key, OracleType.UInt32).Value = values[key];
                            break;
                        case "Int16":
                            ora_com.Parameters.Add(key, OracleType.Int16).Value = values[key];
                            break;
                        case "Int32":
                            ora_com.Parameters.Add(key, OracleType.Int32).Value = values[key];
                            break;
                        case "Int64":
                            ora_com.Parameters.Add(key, OracleType.Int32).Value = values[key];
                            break;
                        case "String":
                            ora_com.Parameters.Add(key, OracleType.VarChar).Value = values[key];
                            break;
                        case "double":
                        case "Double":
                        case "float":
                        case "Decimal":
                            ora_com.Parameters.Add(key, OracleType.Number).Value = values[key];
                            break;
                        case "DateTime":
                            ora_com.Parameters.Add(key, OracleType.DateTime).Value = values[key];
                            break;
                        default:
                            MessageBox.Show("не известный тип " + tp2.Name + " параметра " + key + "");
                            break;
                    }


                }


                if (return_size > 0)
                {
                    ora_com.Parameters.Add("ret", return_type, return_size).Direction =
                        ParameterDirection.ReturnValue;
                }
                else
                {
                    ora_com.Parameters.Add("ret", return_type).Direction =
                        ParameterDirection.ReturnValue;
                }


                int rowsAffected = ora_com.ExecuteNonQuery();
                object ret1 = (ora_com.Parameters["ret"].Value);
                return ret1;

            }catch(Exception ex)
            {

                string ss = " Функция= '" + spf + "' " ;

                foreach (string s in values.Keys)
                {
                    ss = ss + " "+s+"='"+values[s]+"'; ";
                }

                MessageBox.Show("Ошибка функции wms_get_spfunction_value2." + ex.Message + ss);
            }
            return null;
        }


