        bool check_logopar_in_sm(List<string> sts)
        {
            string strSQL1="";
            foreach( string  h in sts )
                strSQL1=strSQL1+",'"+h+"'";

            strSQL1= strSQL1.Trim(',');

            OracleCommand ora_com2 = new OracleCommand();
            OracleConnection ora_con2 = new OracleConnection();
            ora_con2.ConnectionString = SM_CONNECTION_STRING();
            ora_con2.Open();
            ora_com2.Connection = ora_con2;
            // СНАЧАЛА ПОЛУЧИМ ВСЕ ПАРАМЕТРЫ ЗАКАЗА

            string str66 = " SELECT  distinct s.article  " +
                    "  FROM supermag.smdocuments d, " +
                    "  supermag.smspec s, " +
                    "  supermag.smcard  c  " +
                    "  WHERE d.doctype IN ('SO', 'OR') " +
                    "  AND d.docstate IN (1, 2, 3) " +
                    "  AND d.ID in ( " + strSQL1 + " ) " +
                    "  AND d.ID = s.docid " +
                    "  AND d.doctype = s.doctype " +
                    "  AND s.article = c.article  ";
            ora_com2.CommandText = str66;

            OracleDataReader ora_read=  ora_com2.ExecuteReader();
            bool ret1 = true;

            while( ora_read.Read() )
            {
                ret1 = ( ret1 && check_log_par(ora_read.GetString(0)));
            }
            return true;
        }

        private bool check_log_par( string articul1 )
        {
            string mess = "";
            string strSQL = "select  COUNT_SHT_IN_KOR,DIMKOR_X*DIMKOR_Y*DIMKOR_Z XYZ ,BRUTTO_WEIGHT_OF_KOR   from rrl_articuls where acticul ='" + articul1 + "'  ";
            List<Dictionary<object, object>> arr=  get_wms_sql_result_dictionary3( strSQL );
            if (arr.Count == 1)
            {
                if (obj2double(arr[0]["COUNT_SHT_IN_KOR"]) == 0)
                {
                    //MessageBox.Show( articul1+": не указана вложенность в коробки.");
                    Сообщения_загрузки_ст.Text = Сообщения_загрузки_ст.Text + articul1 + ": не указана вложенность в коробки. \n";

                    return false;
                }

                if (obj2double(arr[0]["XYZ"]) == 0)
                {
                    //MessageBox.Show(articul1 + ": нулевой объем коробки.");
                    Сообщения_загрузки_ст.Text = Сообщения_загрузки_ст.Text + articul1 + ": нулевой объем коробки. \n";
                    return false;
                }

                if (obj2double(arr[0]["BRUTTO_WEIGHT_OF_KOR"]) == 0)
                {
                    //MessageBox.Show(articul1 + ": нулевой вес.");
                    Сообщения_загрузки_ст.Text = Сообщения_загрузки_ст.Text + articul1 + ": нулевой вес. \n";
                    return false;
                }

            }


            return true;
        }

