                                    ora_com.Parameters.Add("price", OracleType.Number).Value = Цена_с_ндс;

                                    ora_com.Parameters.Add("ID", OracleType.Int32).Direction = ParameterDirection.ReturnValue;
                                    int rowsAffected44 = ora_com.ExecuteNonQuery();

