        private void SaveST2File(string ST_ID)
        {

            string strSQL2 = " select " +
            " count( DISTINCT P.PALLET_UID ) Q  " +
            " from " +
            " RABAEV.RRL_SBORKA_PALLETS P , " +
            " RABAEV.RRL_SBORKA_PALLET_ROWS R " +
            " where   R.ARTICUL <>'Т0000012233' and (R.QUANTITY>0) and P.PALLET_UID = R.PALLET_UID " +
            " and P.ST_NUMBER='" + ST_ID + "' and (( P.CONDITION<>2  ) and ( P.PROOVED<>1 and  P.PROOVED_BY_SCAN<>1 )  )" +
            " group by R.ARTICUL ";

            int y= obj2int32(get_wms_sql_result_single(strSQL2)) ;
            if ( y>0)
            { 
                MessageBox.Show("Не проведено "+y.ToString()+" паллет");
                return;
            }


            OracleCommand ora_comm = new OracleCommand();
            ora_comm.Connection = get_wms_connection();
            string strSQL = " select " +
            " R.ARTICUL , " +
            " sum(R.QUANTITY) Q  " +
            " from " +
            " RABAEV.RRL_SBORKA_PALLETS P , " +
            " RABAEV.RRL_SBORKA_PALLET_ROWS R " +
            " where (R.QUANTITY>0) and P.PALLET_UID = R.PALLET_UID " +
            " and P.ST_NUMBER='" + ST_ID + "' " +
            " group by R.ARTICUL ";
            ora_comm.CommandText = strSQL;
            OracleDataReader reader = ora_comm.ExecuteReader();

            string path = @"c:\WMS\" + ST_ID + ".txt";
            string ioio = "АРТИКУЛ\n";
            while (reader.Read())
            {
                string art = reader.GetValue(0).ToString();
                double q = Convert.ToDouble(reader.GetValue(1));
                string tr = art + " " + q + "\n";
                ioio = ioio + tr;
            }
            File.WriteAllText(path, ioio, Encoding.GetEncoding("windows-1251"));
            MessageBox.Show(" Выгружен " + path);

        }

        private void SavePRIHOD2File(long PRIHOD_ID)
        {

            string strSQL9 = " select ID from RABAEV.RRL_PRIHOD_NAKLAD where CONDITION=2 and ID=" + PRIHOD_ID.ToString() + " ";
            if (obj2int32( get_wms_sql_result_single( strSQL9)) > 0)
            {

            }
            else {
                MessageBox.Show("Приход не закрыт. Закройте приход во 2-й статус.");
                return;
            }


            OracleCommand ora_comm = new OracleCommand();
            ora_comm.Connection = get_wms_connection();
            string strSQL = "select   RR.ARTICUL , sum( RR.UNIT_COUNT * ((100-AA.DEF_PERC)/100) )  КОЛ " +
            "   from  RABAEV.RRL_PALLETS RR , rrl_articuls AA " +
            "   where PRIHOD_NAKLAD_ID=" + PRIHOD_ID.ToString() + " and RR.ARTICUL=AA.acticul  " +
            "   group by RR.ARTICUL ";

            ora_comm.CommandText = strSQL;
            OracleDataReader reader = ora_comm.ExecuteReader();

            string path = @"c:\WMS\PR" + PRIHOD_ID.ToString() + ".txt";
            string ioio = "АРТИКУЛ\n";
            while (reader.Read())
            {
                string art = reader.GetValue(0).ToString();
                double q = Convert.ToDouble(reader.GetValue(1));
                string tr = art + " " + q + "\n";
                ioio = ioio + tr;
            }
            File.WriteAllText(path, ioio, Encoding.GetEncoding("windows-1251"));
            MessageBox.Show(" Выгружен " + path);

            

        }


