        #region ДЕКОДИРОВАНИЕ

        string pallet_uid_decode(string puid)
        {
            if (puid.IndexOf("W") == -1)
            {
                string f = puid.Replace("OP_", "");
                return "OP_" + Encoding.GetEncoding("windows-1251").GetString((Convert.FromBase64String(f)));
            }
            else {
                string p2 = puid;
                p2=p2.Replace("W", "");
                string[] s = p2.Split('P');
                string strSQL = "select  PALLET_UID  from RRL_SBORKA_PALLETS where ware_id=" + s[0] + " and  ID="+s[1]+" ";
                string ret = CachedQuerySingle(strSQL);
                return ret;
            }
        }

        string pallet_uid_code(string PUID)
        {

            string strSQL = "select concat( concat( 'W' , to_char( ware_id ) ) , concat( 'P' , to_char ( ID ) ) )   from RRL_SBORKA_PALLETS where  PALLET_UID ='" + PUID + "' ";
            string ret = CachedQuerySingle(strSQL);
            return ret;
            string f = PUID.Replace("OP_", "");
            return "OP_" + Convert.ToBase64String((Encoding.GetEncoding("windows-1251").GetBytes(f)));
        }

        #endregion


