                    #region добавляем (УДАЛЯЕМ) СТ ПРИ ПОМОЩИ ХРАНИМОЙ ПРОЦЕДУРЫ

                    ora_com.CommandText = "RABAEV.RRL_TT_ADD_PALL";
                    ora_com.CommandType = CommandType.StoredProcedure;
                    ora_com.Parameters.Add("TT_ID", OracleType.Int32).Value = 0;
                    ora_com.Parameters.Add("ST_NUMBER1", OracleType.VarChar).Value = stn;
                    ora_com.Parameters.Add("user_id1", OracleType.VarChar).Value = this.wms_user.user_id;

                    ora_com.Parameters.Add("ret", OracleType.VarChar, 1024).Direction = ParameterDirection.ReturnValue;

                    int rowsAffected = ora_com.ExecuteNonQuery();



                    #endregion



                    dataGridView20.Rows.Remove(dr);
                }

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
            }


        }



        private string WARE_BY_ID(long id)
        {
            return CachedQuerySingle("select from RRL_WARES where ID=" + id.ToString());
        }

        private string WARE_2_ID(string name)
        {
            string ret = CachedQuerySingle("select ID from RRL_WARES where Name='" + name.ToString().Trim(',').Trim('\'') + "' ");
            if (ret == "") return "0";
            return ret;
        }

        private string WARES_2_IDS(string names)
        {
            string ret = "";
            foreach (string s in names.Split(','))
            {
                if (s.Trim() != "")
                {
                    ret = ret + s.Trim() + ",";
                }
            }
            ret = ret.Trim(',');
            return ret;
        }

        int WARE_ID_BY_ADDR(string path)
        {
            string ch = path.Substring(0, 1);

            int ret=obj2int32( CachedQuerySingle(" select ID from  RABAEV.RRL_WARES where PREFIX='" + ch + "' "));
            if (ret > 0)
            {
                return ret;
            }

            switch (ch)
            {

                case "B": return 4;
                case "I": return 5;
                case "O": return 6;
                case "О": return 6;
                case "D": return 7;
                case "V": return 8;
                case "C": return 1;

                case "N": return 2;
                case "Н": return 2;

                case "M": return 3;
                case "М": return 3;
                case "A": return 3;
                case "А": return 3;

                case "Г": return 8;
                case "В": return 8;
                case "Д": return 7;
                case "Б": return 4;


                case "С": return 1;
                case "R": return 10;
                case "E": return 11;
                case "Е": return 11;

            }

            try
            {
                string h = comboBox1.Text.Substring(0, 1);
                int i = Convert.ToInt32(h);
                return i;
            }
            catch { }

            return 0;

        }


