            _tble78.add_column("СКЛАД", "string", "СКЛАД", 5);
            _tble78.add_column("ВРЕМЯОТ", "string", "Время от", 8);
            _tble78.add_column("ВРЕМЯДО", "string", "Время до", 8);

            while (ora_read78.Read())
            {
                Dictionary<string, string> _row78 = new Dictionary<string, string>();
