                pd.DefaultPageSettings.Landscape = false;
                pd.PrintPage += new PrintPageEventHandler
                    (pd_PrintPage_SBOR);
                pd.Print();
            }
            catch (Exception ex)
            {
                MessageBox.Show(" f48 " + ex.Message);
            }
            #endregion



        }

