        private void dataGrid_pallets_CellEndEdit(object sender, DataGridViewCellEventArgs e)
        {

            // EXPIRY_DATE

            string PALLET_ID = dataGrid_pallets.CurrentRow.Cells[0].Value.ToString();
            string art = dataGrid_pallets.CurrentRow.Cells[1].Value.ToString();
            bool act_count = false;
            bool act_weight = false;
            long type_w = 0;
            type_w = obj2int(dataGrid_pallets.CurrentRow.Cells[15].Value.ToString());

            // БРАК
            bool act_update = false;
            long COUNT_KOR = obj2int(dataGrid_pallets.CurrentRow.Cells[14].Value); ;
            double DEFECT_PERC = obj2double(dataGrid_pallets.CurrentRow.Cells[13].Value);
            double UNIT_COUNT = obj2double(dataGrid_pallets.CurrentRow.Cells[2].Value);
            double WEIGHT_TN = 0;
            WEIGHT_TN = obj2double(dataGrid_pallets.CurrentRow.Cells[10].Value);
            double WEIGHT_BRUTTO = obj2double(dataGrid_pallets.CurrentRow.Cells[11].Value);

            long MOD_ID = obj2int(dataGrid_pallets.CurrentRow.Cells[16].Value.ToString());

            int condition = obj2int32(get_wms_sql_result_single(" select nl.CONDITION  " +
                " from RABAEV.RRL_PALLETS pts , RABAEV.RRL_PRIHOD_NAKLAD nl " +
                " where pts.PRIHOD_NAKLAD_ID=nl.ID and pts.UID_PALLET='" + PALLET_ID + "' "));

            if (condition > 1 && !has_right("CHANGE_PRIHOD_AFTER_ACCEPT") && (e.ColumnIndex != 13))
            {
                MessageBox.Show("Нет прав на изменение прихода после его закрытия.");
                return;
            }

            #region СРОКИ ГОДНОСТИ
            if (e.ColumnIndex == 4)
            {
                DateTime o = Convert.ToDateTime(dataGrid_pallets.CurrentRow.Cells[4].Value);
                if (o != null)
                {

                    OracleCommand ora_com = new OracleCommand();
                    ora_com.Connection = get_wms_connection();
                    ora_com.CommandText = " update RABAEV.RRL_PALLETS set EXPIRY_DATE = " + date2sql_ora(o) + " where UID_PALLET='" + PALLET_ID + "' ";
                    ora_com.ExecuteNonQuery();

                }
            }
            #endregion


            #region Количество коробок
            if (e.ColumnIndex == 14)
            {
                act_update = true;
            }
            #endregion

            #region БРАК
            if (e.ColumnIndex == 13)
            {
                act_update = true;
            }
            #endregion

            #region  КОЛИЧЕСТВО ИЗМЕНИЛОСЬ
            if ((e.ColumnIndex) == 2)
            {
                act_update = true;
            }
            #endregion

            #region ВЕС ТН ИЗМЕНИЛСЯ.
            if (e.ColumnIndex == 10)
            { // Вес ТН изменился 

                act_update = true;

            }
            #endregion

            #region Изменение веса паллета
            if (e.ColumnIndex == 11)
            { // Поменяли вес 
                act_update = true;
            }
            #endregion

            #region ФАСОВКА

            if (e.ColumnIndex == 12 && (type_w == 1 || type_w == 2 || type_w == 5 || type_w == 6 || type_w == 7 || type_w == 8)) // Фасовка. 
            {
                string val = obj2str(dataGrid_pallets.CurrentRow.Cells[e.ColumnIndex].Value);
                string strSQL = "select count(ID)  from RRL_ARTICUL_MODS  where ARTICUL='"
                    + art + "' and deleted<>1 ";

                long count_of_c = obj2int(get_wms_sql_result_single(strSQL));

                if (count_of_c > 0)
                {
                    strSQL = "select (ID) , NAME from RRL_ARTICUL_MODS  where ARTICUL='"
                        + art + "' and deleted<>1 ";
                    object[] g = ShowQuery(strSQL, "Выберите фасовку артикула " + art, new Point(0, 1), val);
                    if (g.Length > 0)
                    {
                        long ID_ = obj2int(g[0]);
                        string name_ = obj2str(g[1]);
                        if (ID_ > 0)
                        {
                            dataGrid_pallets.CurrentRow.Cells[e.ColumnIndex].Value = name_;
                            OracleCommand ora_com = new OracleCommand();
                            ora_com.Connection = get_wms_connection();
                            ora_com.CommandText = " update RABAEV.RRL_PALLETS set MOD_ID = " + ID_.ToString() + " where UID_PALLET='" + PALLET_ID + "' ";
                            ora_com.ExecuteNonQuery();
                            MOD_ID = ID_;
                            act_update = true;

                            ExecuteOracleNonQuery(
                            " update RABAEV.RRL_ARTICULS set LAST_MOD_ID = " + ID_.ToString() +
                            " where     ACTICUL='" + art + "' ");

                        }
                    }

                }
                else
                {
                    // У артикула нет модификаций.
                    MessageBox.Show("У данного товара не создано фасовок");
                }

            }

            #endregion

            #region Изменение процента брака 
            if ( e.ColumnIndex == 13 )
            { // Поменяли вес 
                if (condition > 1)
                {
                    if( !has_right("UPDATE_DEFECT_PERC") ){
                        MessageBox.Show( "Нет прав на изменение процента брака в закрытой накладной" );
                        return;
                    }

                    object[] o = ShowQuery(" select ID , Name from RRL_PALL_TRASH_REASON " , "Выберите причину изменения процента брака" );
                    if (o.Length > 0)
                    {
                        int id_res = obj2int32( o[0].ToString());
                        if (id_res > 0)
                        {
                            ExecuteOracleNonQuery(" update   RABAEV.RRL_PALLETS set REASON_ID=" + id_res.ToString()+ " where UID_PALLET='" + PALLET_ID + "' ");

                            Dictionary<string , object> values  =  new Dictionary<string,object>();
                            values["puid1"] =  PALLET_ID ;
                            values["new_perc"] = DEFECT_PERC ;
                            values["reason_id"] = id_res;
                            object ret = wms_get_spfunction_value2("PRIHOD.set_brak_perc_new", values, OracleType.Int32, 0);

                        }
                        else {
                            MessageBox.Show("Укажите причину изменения процента брака");
                            return;
                        }


                    }

                }
            }
            #endregion




            #region ВЫЧИСЛЕНИЕ ЗАВИСИМЫХ ПАРАМЕТРОВ и ОБНОВЛЕНИЕ
            if (act_update)
            {





                #region Вносим изменения в данный паллет

                OracleCommand ora_com7 = new OracleCommand();
                ora_com7.Connection = get_wms_connection();
                ora_com7.CommandText = "RABAEV.RRL_PRIHODPALLET_CHANGE";
                ora_com7.CommandType = CommandType.StoredProcedure;

                ora_com7.Parameters.Add("PALLET_UID1", OracleType.VarChar).Value = PALLET_ID;
                ora_com7.Parameters.Add("art", OracleType.VarChar).Value = art;
                ora_com7.Parameters.Add("UNIT_COUNT1", OracleType.Number).Value = UNIT_COUNT;
                ora_com7.Parameters.Add("DEFECT_PERC1", OracleType.Number).Value = DEFECT_PERC;
                ora_com7.Parameters.Add("COUNT_KOR1", OracleType.Int32).Value = COUNT_KOR;
                ora_com7.Parameters.Add("WEIGHT_BRUTTO1", OracleType.Number).Value = WEIGHT_BRUTTO;
                ora_com7.Parameters.Add("WEIGHT_TN1", OracleType.Number).Value = WEIGHT_TN;
                ora_com7.Parameters.Add("MOD_ID1", OracleType.Int32).Value = MOD_ID;

                ora_com7.Parameters.Add("ret", OracleType.VarChar, 255).Direction = ParameterDirection.ReturnValue;
                int rowsAffected7 = ora_com7.ExecuteNonQuery();
                string ret = (ora_com7.Parameters["ret"].Value.ToString());
                if (ret != "OK")
                {
                    MessageBox.Show(ret);
                    return;
                }
                #endregion
                string strSQL5 = "select " +
                " UNIT_COUNT   , DEFECT_PERC   , COUNT_KOR  , " +
                " WEIGHT_BRUTTO   , WEIGHT_TN   , MOD_ID     " +
                " from RRL_PALLETS   where UID_PALLET = '" + PALLET_ID + "' ";
                OracleCommand ora_com6 = new OracleCommand();
                ora_com6.Connection = get_wms_connection();
                ora_com6.CommandText = strSQL5;
                OracleDataReader ora_read = ora_com6.ExecuteReader();
                if (ora_read.Read())
                {
                    dataGrid_pallets.CurrentRow.Cells[2].Value = ora_read.GetValue(0).ToString();
                    dataGrid_pallets.CurrentRow.Cells[13].Value = ora_read.GetValue(1).ToString();
                    dataGrid_pallets.CurrentRow.Cells[14].Value = ora_read.GetValue(2).ToString();
                    dataGrid_pallets.CurrentRow.Cells[11].Value = ora_read.GetValue(3).ToString();
                    dataGrid_pallets.CurrentRow.Cells[10].Value = ora_read.GetValue(4).ToString();
                    MOD_ID = obj2int(ora_read.GetValue(5).ToString());
                    if (MOD_ID == 0)
                    {
                        dataGrid_pallets.CurrentRow.Cells[12].Value = "-";
                    }
                    dataGrid_pallets.CurrentRow.Cells[16].Value = MOD_ID;
                }


            }
            #endregion

        }
        #endregion

