        private void dataGridView8_CellValueChanged(object sender, DataGridViewCellEventArgs e)
        {
            if (e == null) return;
            if (e.RowIndex < 0 )
                return;

            if (e.ColumnIndex == 0 || e.ColumnIndex == 1)
                return;

            DataGridViewRow dr = dataGridView8.Rows[e.RowIndex];
            if (dataGridView8.CurrentRow == null)
            {
                return;
            }
            string cell = dr.Cells[1].Value.ToString();
            int otbor = 0;
            int BLOCKED_FOR_ACCEPT = 0;
            int BLOCKED_FOR_REMAINS = 0;
            int BLOCKED_FOR_POPOLNENIE = 0;

            if (Convert.ToBoolean(dr.Cells[2].Value))
            {
                otbor = 1;
            }

            double ВЕС = obj2int32(dr.Cells[11].Value);
            double ВЫСОТА = obj2int32(dr.Cells[12].Value);
            int ware_id1 = obj2int32(dr.Cells[13].Value);
            int порядок_обхода = obj2int32(dr.Cells[14].Value);

            int X = obj2int32(dr.Cells[3].Value);
            int Y = obj2int32(dr.Cells[4].Value);
            int Z = obj2int32(dr.Cells[5].Value);


