        private double pall_2_numb( string sss ) {

            double sm = 0;
            double multiplicator=1;
            foreach (string ch1 in sss.Split(','))
            {
                string ch2 = ch1;
                ch2 = ch2.Replace(",", "");
                if (ch2 != "") // --------------------------------------------------------
                { 
                    if( ch2.IndexOf("RP")!=-1 )
                    {
                         ch2=ch2.Replace("RP","" );
                         multiplicator=0.5;
                    }else{

                        if (ch2.IndexOf("P") != -1)
                        {
                            ch2 = ch2.Replace("P", "");
                            multiplicator = 1;
                        }
                        else {
                            if (ch2.IndexOf("V") != -1)
                            {
                                ch2 = ch2.Replace("V", "");
                                multiplicator = 1.2;
                            }
                            else {
                                if (ch2.IndexOf("R") != -1)
                                {
                                    ch2 = ch2.Replace("R", "");
                                    multiplicator = 0.5;
                                }
                                else {
                                    if (ch2.IndexOf("T") != -1)
                                    {
                                        ch2 = ch2.Replace("T", "");
                                    }
                                }
                            }
                        }
                    
                    }
                } // Конец анализа
                // ----------------------------------------------------------------------
                sm = sm + obj2double(ch2) * multiplicator;
            }
            return sm;
        }

