                    }
                    #endregion

                    double kolpal = obj2double(df["kolpal"]);
                    long srok_godnosti = obj2int(df["expirationdate"]);

                    ora_com = new OracleCommand();
                    ora_com.Connection = get_wms_connection();
                    ora_com.CommandText = "ADD_RRL_PRIH_NAKLAD_ROW2";
