        private void dataGridView23_KeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.F5)
            {

                foreach (DataGridViewRow dr in dataGridView23.Rows)
                {
                    dr.Cells[8].Value = dr.Cells[0].Selected;
                }
            }

            if (e.KeyCode == Keys.F6)
            {

                foreach (DataGridViewRow dr in dataGridView23.Rows)
                {
                    dr.Cells[8].Value = false;
                }
            }

            if (e.KeyCode == Keys.F1)
            {

                if (dataGridView23.CurrentRow == null)
                    return;

                double resd = 0;
                bool durty = false;
                long rid = obj2int(dataGridView23.CurrentRow.Cells[3].Value);
                string ret2 = obj2str(get_wms_sql_result_single(" select manual_input from RRL_SBORKA_PALLET_ROWS where ID=" + rid.ToString() + "  "));

                string ret = ask("Введите веса коробок через пробел", "Введите веса коробок через пробел", ret2);
                if (ret == "") return;
                if (ret == null) return;

                ret = ret.Replace('+', ' ');
                ExecuteOracleNonQuery(" update RRL_SBORKA_PALLET_ROWS set manual_input='" + ret + "' where  ID=" + rid.ToString() + " ");
                if (ret.Trim() != "")
                {
                    ret = ret.Replace('.', ',');
                    ret = ret.Replace('ю', ',');
                    ret = ret.Replace('?', ',');
                    ret = ret.Replace('/', ',');

                    string[] hh = ret.Split(' ');
                    foreach (string h in hh)
                    {
                        if (h.Trim() != "")
                        {
                            if (obj2double(h) > 0)
                            {
                                resd = resd + obj2double(h);
                            }
                            else
                            {
                                durty = true;
                                MessageBox.Show(h + " не является числом. ");
                            }
                        }
                    }

                }

                if (resd > 0 && !durty)
                {
                    dataGridView23.CurrentRow.Cells[2].Value = resd;

                    DataGridViewCellEventArgs e1 = new DataGridViewCellEventArgs(2, dataGridView23.CurrentRow.Index);
                    
