        private void удалитьПустойПаллетToolStripMenuItem_Click(object sender, EventArgs e)
        {
            int row_count = dataGridView23.Rows.Count;

            if( row_count==1  )
                if(dataGridView23.Rows[0].Cells[0].Value==null )
                {
                    row_count=0;
                }

            if ( row_count != 0)
            {
                MessageBox.Show("Паллет не пустой!");
