                    {
                        strSQL2 = strSQL2 + " (PAL.pallet_uid like '%" + split.GetValue(0).ToString() + "%'  and ROWSs.ARTICUL='" + split.GetValue(1).ToString() + "' ) or";

                    }
                    else
                    {
                        strSQL2 = strSQL2 + " (PAL.pallet_uid like '%" + lll2 + "%') or";
                    }
