        private void dataGridView22_CellFormatting(object sender, DataGridViewCellFormattingEventArgs e)
        {


            if (e.ColumnIndex == 1)
            {
                if (dataGridView22.Rows.Count == 0) return;
                object o=dataGridView22[5, e.RowIndex].Value;
                if ( o== null) return;


                if (((o.ToString()) == "2"))
                {
                    e.CellStyle.BackColor = Color.Green;
                }

                if (((o.ToString()) == "1"))
                {
                    e.CellStyle.BackColor = Color.LightCoral;
                }
                
                if (((o.ToString()) == "3")) // Недокаченное из внешней системы
                {
                    e.CellStyle.BackColor = Color.Red;
                }
                
                if (((o.ToString()) == "4")) // Закаченное из внешней системы
                {
                    e.CellStyle.BackColor = Color.SkyBlue;
                }
            }

        }

