        public void СравнитьСпускИОтбор( List<string> articuls , DateTime ДатаОт , DateTime ДатаДо  )
        {
            string arts = "";
            foreach (string lin in articuls)
            {
                arts = arts + "'" + lin + "',";
            }

            arts = arts.Trim(',').Trim();

            string strSQL1 = "      select  concat( TO_CHAR(  COMPL.pallet_compl_date( pp.PALLET_UID ), 'dd-mm-yyyy'  )   , rr.ARTICUL  ) КЛЮЧ , " +
            " TO_CHAR( COMPL.pallet_compl_date( pp.PALLET_UID ) , 'dd-mm-yyyy'  ) ДАТА ," +
            " sum( quantity ) КОЛВО_В_МАГАЗИНЫ , " +
            " rr.ARTICUL " +
            " from RABAEV.RRL_SBORKA_PALLET_ROWS rr  ,   RABAEV.RRL_SBORKA_PALLETS pp   " +
            " where  " +
            " rr.PALLET_UID = pp.PALLET_UID  and  " +
            " rr.ARTICUL in ( " + arts + " )  " +
            " and ( pp.CREATE_DATE >= " + date2sql_ora(ДатаОт.AddDays(-1)) + " ) " +
            " and ( pp.CREATE_DATE <= " + date2sql_ora(ДатаДо.AddDays(0)) + " ) " +
            " group by  TO_CHAR( COMPL.pallet_compl_date( pp.PALLET_UID ) , 'dd-mm-yyyy'  ) , " +
            " rr.ARTICUL , concat( TO_CHAR( COMPL.pallet_compl_date( pp.PALLET_UID ), 'dd-mm-yyyy'  )   , rr.ARTICUL  ) ";
            
            //ShowQuery(strSQL1, "Сколько отгружено на магазины.");

             Dictionary< object ,Dictionary<object, object>> Сколько_отгружено_на_магазины =  get_wms_sql_result_dictionary2(strSQL1);

             string strSQL2 = " select  concat( TO_CHAR( ee.date_event , 'dd-mm-yyyy'  ) , PP.ARTICUL ) КЛЮЧ  , "+
                 "  TO_CHAR( ee.date_event , 'dd-mm-yyyy'  ) ДАТА , " +
            "              sum( count_event ) КОЛВО_В_ОТБОР ,  " +
            "              PP.ARTICUL " +
            "              from rrl_events EE , rrl_pallets PP , rrl_cells CC  " +
            "              where  " +
            "              EE.UID_POLETA = PP.UID_PALLET and  " +
            "              PP.ARTICUL in ( " + arts + " ) and " +
            "              ee.date_event >= " + date2sql_ora(ДатаОт) + "  and " +
            "              ee.date_event <= " + date2sql_ora(ДатаДо) + "  and " +
            "              CC.cell = EE.cell_to and  " +
            "              CC.otbor=1 and  " +
            "              CC.is_system =0 " +
            "              group by TO_CHAR(ee.date_event , 'dd-mm-yyyy'  ) , PP.ARTICUL , concat( TO_CHAR( ee.date_event , 'dd-mm-yyyy'  ) , PP.ARTICUL ) ";


            //ShowQuery(strSQL2, "Сколько спущено в отбор за период.");
            Dictionary<object, Dictionary<object, object>> В_отбор = get_wms_sql_result_dictionary2(strSQL2);


            string strSQL3 = " select acticul , name  from rrl_articuls where acticul in ( " + arts + " ) ";
            Dictionary<object, Dictionary<object, object>> артикулы = get_wms_sql_result_dictionary2(strSQL3);


            List<Dictionary<string, object>> res2 = new List<Dictionary<string, object>>();
            foreach (  object rr in В_отбор.Keys)
            {
                DateTime dd = new DateTime();
                Dictionary<string, object> result_row = new Dictionary<string, object>();

                double Количество_на_магазины = 0;
                if (Сколько_отгружено_на_магазины.ContainsKey(rr))
                {
                    Количество_на_магазины = obj2double(Сколько_отгружено_на_магазины[rr]["КОЛВО_В_МАГАЗИНЫ"]);
                    Сколько_отгружено_на_магазины.Remove(rr);
                }
                result_row["АРТИКУЛ"] = В_отбор[rr]["ARTICUL"];
                result_row["дата"] = В_отбор[rr]["ДАТА"];
                result_row["Спущено_в_отбор"] = В_отбор[rr]["КОЛВО_В_ОТБОР"];
                result_row["Отрг_На_Магазины"] = Количество_на_магазины;
                result_row["Разница"] = obj2double(В_отбор[rr]["КОЛВО_В_ОТБОР"]) - Количество_на_магазины;
                result_row["ИмяТовара"] = артикулы[В_отбор[rr]["ARTICUL"]]["NAME"];

                dd = obj2DateTime(В_отбор[rr]["ДАТА"]);
                result_row["День"] = dd.Day;
                result_row["Месяц"] = dd.Month;
                result_row["Год"] = dd.Year;


                res2.Add(result_row);
            }


            foreach (object rr in Сколько_отгружено_на_магазины.Keys)
            {
                DateTime dd = new DateTime();
                Dictionary<string, object> result_row = new Dictionary<string, object>();
                double спущено_в_отбор = 0;

                result_row["АРТИКУЛ"] = Сколько_отгружено_на_магазины[rr]["ARTICUL"];
                result_row["дата"] = Сколько_отгружено_на_магазины[rr]["ДАТА"];
                result_row["Спущено_в_отбор"] = спущено_в_отбор;
                result_row["Отрг_На_Магазины"] = Сколько_отгружено_на_магазины[rr]["КОЛВО_В_МАГАЗИНЫ"];
                result_row["Разница"] = - obj2double(Сколько_отгружено_на_магазины[rr]["КОЛВО_В_МАГАЗИНЫ"]) ;
                result_row["ИмяТовара"] = артикулы[Сколько_отгружено_на_магазины[rr]["ARTICUL"]]["NAME"];

                dd = obj2DateTime(Сколько_отгружено_на_магазины[rr]["ДАТА"]);
                result_row["День"] = dd.Day;
                result_row["Месяц"] = dd.Month;
                result_row["Год"] = dd.Year;

                res2.Add(result_row);
            }

            

            ЗАПРОСЫ Z = new ЗАПРОСЫ();
            Z.res = res2;
            Z.ShowDialog();



            return;

           

            

        }



