        private void обновитьСправочникЗонОтгрузкиИзExcelToolStripMenuItem_Click(object sender, EventArgs e)
        {

            Excel.Application oExcelApp = new Excel.Application();
            oExcelApp.Visible = true;

            object obj = new object();
            string Filename = "C:\\WMS\\zones.xls";
            long pos = 2;
            try
            {


                try
                {

                    oExcelApp.Workbooks.Open(Filename, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing);
                    pos = 1;

                    if (
                    ((Excel.Range)oExcelApp.Cells[pos, 1]).Value2.ToString() != "ЗОНА" ||
                    ((Excel.Range)oExcelApp.Cells[pos, 2]).Value2.ToString() != "ПОДЗОНА" ||
                    ((Excel.Range)oExcelApp.Cells[pos, 3]).Value2.ToString() != "ДОК" ||
                    ((Excel.Range)oExcelApp.Cells[pos, 4]).Value2.ToString() != "X" ||
                    ((Excel.Range)oExcelApp.Cells[pos, 5]).Value2.ToString() != "Y"
                        )
                    {
                        MessageBox.Show(" файл должен иметь структуру: ЗОНА - ПОДЗОНА - ДОК - X - Y ");
                        return;
                    }


                }
                catch (Exception ex)
                {
                    MessageBox.Show(ex.Message);
                    return;
                }


                pos++;


                while (((Excel.Range)oExcelApp.Cells[pos, 1]).Value2 != null)
                {
                    string ZONE1 = "";
                    string SUB_ZONE1 = "";
                    string DOCK1 = "";
                    double X = 0;
                    double Y = 0;

                    try
                    {
                        ZONE1 = ((Excel.Range)oExcelApp.Cells[pos, 1]).Value2.ToString();
                        SUB_ZONE1 = ((Excel.Range)oExcelApp.Cells[pos, 2]).Value2.ToString();
                        DOCK1 = ((Excel.Range)oExcelApp.Cells[pos, 3]).Value2.ToString();

                        X = Convert.ToDouble(((Excel.Range)oExcelApp.Cells[pos, 4]).Value2.ToString().Replace('.', ','));
                        Y = Convert.ToDouble(((Excel.Range)oExcelApp.Cells[pos, 5]).Value2.ToString().Replace('.', ','));
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show(" Не могу закачать данные из строчки " + pos.ToString() + " " + ex.Message);
                        return;
                    }


                    OracleCommand ora_com = new OracleCommand();
                    ora_com.Connection = get_wms_connection();

                    ora_com.CommandText = "RABAEV.RRL_UPDATE_TT_ZONE";
                    ora_com.CommandType = CommandType.StoredProcedure;

                    ora_com.Parameters.Add("ZONE1", OracleType.VarChar).Value = ZONE1;
                    ora_com.Parameters.Add("SUB_ZONE1", OracleType.VarChar).Value = SUB_ZONE1;
                    ora_com.Parameters.Add("DOCK1", OracleType.VarChar).Value = DOCK1;
                    ora_com.Parameters.Add("X1", OracleType.Number).Value = X;
                    ora_com.Parameters.Add("Y1", OracleType.Number).Value = Y;

                    ora_com.Parameters.Add("tmpVar", OracleType.Int32).Direction = ParameterDirection.ReturnValue;
                    int rowsAffected = ora_com.ExecuteNonQuery();
                    string tmpVar = ora_com.Parameters["tmpVar"].Value.ToString();
                    // ================================================================
                    pos++;
                }
                MessageBox.Show("Данные выгружены в Excel");
            }
            catch (Exception ex)
            {
                MessageBox.Show(Convert.ToString(pos) + " _ " + ex.Message);
            }
            // ================================


        }

