        private void Печать_сравнения_1_ст(string ST)
        {
            // Сначала определяем количество поддонов.
            // Дату ст , адрес
            DateTime дата_ст = new DateTime();
            string адрес = "";
            long количество_паллет = 0;
            long количество_распечаток = 0;

            количество_распечаток = obj2int(get_wms_sql_result_single(" select   max(COUNT_OF_PRINTS2) " +
                " from RABAEV.RRL_SBORKA_PALLETS where ST_NUMBER = '" + ST + "' "));

            if (количество_распечаток > 0)
                if (!has_right("PRINT_OP_PASSPORT_UNLIMIT"))
                {
                    MessageBox.Show("Сравнение " + ST + " уже распечатывалось.");
                    return;
                }

            string strSQL = " select count( PAL.PALLET_UID ) , PAL.ADDR , PAL.STDATE " +
                " from RRL_SBORKA_PALLETS PAL where PAL.ST_NUMBER = '" + ST + "' " +
