        private void сравнитьДокументыСупермагИОраклToolStripMenuItem_Click(object sender, EventArgs e)
        {

            if (dataGridView17.CurrentRow == null) return;

            List<Dictionary<string, object>> res2 = new List<Dictionary<string, object>>();
            string TT_id = dataGridView17.CurrentRow.Cells[1].Value.ToString();

            string strSQL = " select distinct ST_NUMBER from RRL_SBORKA_PALLETS where TRANSTASK_ID = " + TT_id + " ";
