        public void PrintFromXMLFile(string filename, Dictionary<string, Dictionary<string, string>> database, Dictionary<string, string> constants)
        {
            string text = "";
            bool read_ok = false;
            constants["version"]= this.version ;
            constants["filename"] = filename;
            constants["user"] = this.wms_user.user_id;

            try
            {
                
                text = File.ReadAllText(@"C:\WMS\PrintForms\" + filename, Encoding.GetEncoding("windows-1251"));
                read_ok = true;

            }
            catch (Exception ex)
            {
                try
                {
                    text = get_wms_sql_result_single(" select content from RABAEV.RRL_PRINTFORMS where ID='" + filename + "'").ToString();
                    if (text != "")
                    {
                        PrintFromXML(text, database, constants);
                    }
                    else
                    {
                        MessageBox.Show("Нет печатной формы " + filename);
                    }
                }
                catch
                {
                    MessageBox.Show("Нет печатной формы " + filename);
                }
                     
            }

            if (read_ok)
            PrintFromXML(text, database, constants);

            //  File.WriteAllText(path, ioio, Encoding.GetEncoding("windows-1251"));
            


        }

        private string Replace(string str, Dictionary<string, double> m_local_variables)
        {
            string ret = str;
            foreach (string key in m_local_variables.Keys)
            {
                ret=ret.Replace(key, m_local_variables[key].ToString());
            }
            return ret;
        }

        private void deep( XmlNode root , Dictionary<string, string> constants  )
        {


            if (root.Name == "LOOP")
            {
                long _from=0;
                long _to=0;

                if (root.Attributes["from"] != null)
                {
                    foreach (string key in constants.Keys)
                    {
                        root.Attributes["from"].Value = obj2str(  root.Attributes["from"].Value   ).Replace("[" + key + "]", constants[key]); 
                    }


                    _from = (obj2int(   PPage.PTable.eval_math(  root.Attributes["from"].Value) ));
                }
                
                if (root.Attributes["to"] != null)
                {
                    foreach (string key in constants.Keys)
                    {
                        root.Attributes["to"].Value = obj2str(root.Attributes["to"].Value).Replace("[" + key + "]", constants[key]);
                    }
                    _to = (obj2int( PPage.PTable.eval_math(   root.Attributes["to"].Value)));
                }


                for ( long i = _from;  i<=_to ; i++ )
                {
                    constants["loop_counter"]=i.ToString();
                        foreach (XmlNode node in root)
                        {
                            XmlNode node2 = node.Clone();
                            foreach( string c in constants.Keys )
                            node2.InnerXml=node2.InnerXml.Replace( "["+c+"]" , constants[c] );
                            root.ParentNode.AppendChild(node2);
                        }
                }



            } // ----

           foreach (XmlNode node in root)
           {
                    deep(node, constants);
           }
        
           
        }


        public void PrintFromXML(string xml_str, Dictionary<string, Dictionary<string, string>> database, Dictionary<string, string> constants)
        {
            
            

            int first_landscape = -1;
            Dictionary<string, Dictionary<string, XmlNode>> conditions = new Dictionary<string, Dictionary<string, XmlNode>>();// поле - условие - XML
            Dictionary<string, double> m_local_variables = new Dictionary<string, double>();

            try
            {
                Dictionary<string, long> table_positions = new Dictionary<string, long>();
                XmlDocument doc = new XmlDocument();
                string xml_str1 = xml_str;

                if (constants != null)
                    foreach (string h1 in constants.Keys)
                    {
                        xml_str1 = xml_str1.Replace("[" + h1 + "]", constants[h1]);
                    }

                xml_str1 = xml_str1.Replace("[Time]", DateTime.Now.ToShortTimeString() );
                xml_str1 = xml_str1.Replace("[Date]", DateTime.Today.ToShortDateString());

                doc.LoadXml(xml_str1);
                #region ПОДСТАНОВКА ЗНАЧЕНИЙ ПЕРЕМЕННЫХ VAR типа SQL
                try
                {
                    foreach (XmlNode node in doc.ChildNodes[0].ChildNodes)
                    {
                        if (node.Name == "VAR")
                        {
                            string var_name = "";
                            string var_value = "";
                            string var_type = "";
                            string var_sql = "";
                            if (node.Attributes["name"] != null)
                                var_name = obj2str(node.Attributes["name"].Value);
                            var_sql = node.InnerText;
                            if (node.Attributes["type"] != null)
                                var_type = obj2str(node.Attributes["type"].Value);
                            if (var_type == "sql" && var_name != "" && var_sql != "")
                            {

                                // object v = get_wms_sql_result_single(var_sql);
                                // xml_str1 = xml_str1.Replace("[" + var_name + "]", v.ToString());

                                OracleCommand ora_com5 = new OracleCommand();
                                ora_com5.Connection = get_wms_connection();
                                ora_com5.CommandText = var_sql;
                                OracleDataReader ora_read5 = ora_com5.ExecuteReader();
                                int count_of_fields5 = ora_read5.VisibleFieldCount;
                                while (ora_read5.Read())
                                {
                                    for (int i = 0; i < count_of_fields5; i++)
                                    {
                                        string field_name = "";
                                        string field_val = "";
                                        try
                                        {
                                            field_name = ora_read5.GetName(i);
                                            field_val = obj2str(ora_read5.GetValue(i));
                                        }
                                        catch { }
                                        xml_str1 = xml_str1.Replace("[" + var_name + "." + field_name + "]", field_val);
                                    }

                                }
                            }
                            else
                            {
                                if (var_type == "sqlcached" && var_name != "" && var_sql != "")
                                {
                                    string v1 = CachedQuerySingle(var_sql);
                                    xml_str1 = xml_str1.Replace("[" + var_name + "]", v1.ToString());
                                }
                                else
                                {
                                    if (var_type == "" && var_name != "" && var_sql != "")
                                    {
                                        xml_str1 = xml_str1.Replace("[" + var_name + "]", var_sql.ToString());
                                    }

                                }
                            }

                        }
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show("PRINT_ERR:"+ex.Message);
                }
                #endregion
                doc = new XmlDocument();
                doc.LoadXml(xml_str1);

                if (doc.ChildNodes.Count > 1)
                    return;


                deep(doc.ChildNodes[0] , constants );


                foreach (XmlNode node in doc.ChildNodes[0].ChildNodes)
                {
                    if (node.Name == "PAGE")
                    {

                        PPage _p = new PPage();
                        if (node.Attributes["axes"] != null)
                            if (node.Attributes["axes"].Value.ToString() == "1")
                                _p.print_axes();

                        if (node.Attributes["landscape"] != null)
                        {
                            if (obj2int(node.Attributes["landscape"].Value) == 1)
                                _p.Landscape = 1;

                            if (obj2int(node.Attributes["landscape"].Value) == 0)
                                _p.Landscape = 0;

                        }
                        if (first_landscape == -1)
                            first_landscape = _p.Landscape;

                        foreach (XmlNode node2 in node.ChildNodes)
                        {

                            switch (node2.Name)
                            {
                                #region LINE
                                case "LINE":
                                    try
                                    {
                                        
                                        int x1 = 0, y1 = 0, x2 = 0, y2 = 0;
                                        bool rep= false;
                                        if(node2.Attributes["repeat"] != null) 
                                          rep = obj2bool(node2.Attributes["repeat"].Value);

                                        x1 = obj2int32(node2.Attributes["x1"].Value);
                                        y1 = obj2int32(node2.Attributes["y1"].Value);
                                        x2 = obj2int32(node2.Attributes["x2"].Value);
                                        y2 = obj2int32(node2.Attributes["y2"].Value);
                                        _p.arrows.Add(new PPage.PArrow(x1, y1, x2, y2, rep));
                                        
                                    }
                                    catch (Exception ex)
                                    {
                                        MessageBox.Show(" LINE1: "+ex.Message);
                                    }

                                    break;
                                #endregion

                                #region RECT
                                case "RECT":
                                    try
                                    {
                                        bool rep = false;
                                        if (node2.Attributes["repeat"] != null)
                                            rep = obj2bool(node2.Attributes["repeat"].Value);

                                        int x1 = 0, y1 = 0, x2 = 0, y2 = 0 , fill=1;
                                        x1 = obj2int32(node2.Attributes["x1"].Value);
                                        y1 = obj2int32(node2.Attributes["y1"].Value);
                                        x2 = obj2int32(node2.Attributes["x2"].Value);
                                        y2 = obj2int32(node2.Attributes["y2"].Value);


                                        if (node2.Attributes["fill"] != null)
                                            fill = obj2int32 (node2.Attributes["fill"].Value);

                                        _p.arrows.Add(new PPage.PArrow(x1, y1, x2, y1, rep));
                                        _p.arrows.Add(new PPage.PArrow(x1, y1, x1, y2, rep));
                                        _p.arrows.Add(new PPage.PArrow(x1, y2, x2, y2, rep));
                                        _p.arrows.Add(new PPage.PArrow(x2, y1, x2, y2, rep));

                                    }
                                    catch (Exception ex)
                                    {
                                        MessageBox.Show("RECT2:"+ex.Message);
                                    }

                                    break;
                                #endregion

                                #region LABEL
                                case "LABEL":
                                    try
                                    {
                                        bool rep = false;
                                        if (node2.Attributes["repeat"] != null)
                                            rep = obj2bool(node2.Attributes["repeat"].Value);

                                        Brush brush = null;
                                        int x = 0, y = 0;
                                        string type = "text";
                                        long width = 0, height = 0, fontsize = 12;
                                        string inner_text = node2.InnerText;
                                        string replace_from = "", replace_to = "" ;
                                        float angle = 0;
                                        string encode = "";


                                        if (node2.Attributes["encode"] != null)
                                            encode = obj2str(node2.Attributes["encode"].Value);

                                        if (node2.Attributes["angle"] != null)
                                            angle = obj2float(node2.Attributes["angle"].Value);

                                        if (node2.Attributes["replace_from"] != null)
                                            replace_from = obj2str(node2.Attributes["replace_from"].Value);

                                        if (node2.Attributes["replace_to"] != null)
                                            replace_to = obj2str(node2.Attributes["replace_to"].Value);

                                        if (node2.Attributes["fontsize"] != null)
                                            fontsize = obj2int(node2.Attributes["fontsize"].Value);

                                        if (node2.Attributes["width"] != null)
                                            width = obj2int(node2.Attributes["width"].Value);

                                        if (node2.Attributes["height"] != null)
                                            height = obj2int(node2.Attributes["height"].Value);


                                        if (node2.Attributes["x"] != null)
                                        {
                                            x = obj2int32(node2.Attributes["x"].Value);
                                        }

                                        if (node2.Attributes["y"] != null)
                                        {
                                            y = (int)PPage.PTable.eval_table_position(table_positions, node2.Attributes["y"].Value.ToString());
                                            // y = obj2int32(node2.Attributes["y"].Value);
                                        }
                                        if (node2.Attributes["type"] != null)
                                            type = obj2str(node2.Attributes["type"].Value);

                                        if (replace_from != "")
                                            inner_text = inner_text.Replace(replace_from, replace_to);

                                        if (encode == "pallet_uid_code")
                                        {
                                            inner_text = pallet_uid_code(inner_text);
                                        }

                                        if ((width != 0 || height != 0) || type == "EAN")
                                        { // если ширина и высота установлены
                                            PPage.PLabel pl = new PPage.PLabel(inner_text,
                                                 new Point(x, y), fontsize, type, width, height, angle);
                                            pl.repeat = rep;
                                            _p.labels.Add(pl);
                                        }
                                        else
                                        { // Если ширина и высота не установлены 
                                            PPage.PLabel pl = new PPage.PLabel(inner_text,
                                                   new Point(x, y), fontsize, type, angle);
                                            pl.repeat = rep;
                                            _p.labels.Add(pl);
                                        }






                                    }
                                    catch (Exception ex)
                                    {
                                        MessageBox.Show("LABEL : "+ex.Message);
                                    }

                                    break;
                                #endregion

                                #region TABLE
                                case "TABLE":
                                    try
                                    {
                                        string table_name = "";
                                        Dictionary<string, Dictionary<string, string>> field_parameters = new Dictionary<string, Dictionary<string, string>>();
                                        int x1 = 0, y1 = 0, font = 12;
                                        int rows_table_limit = 0;

                                        if (node2.Attributes["rows_table_limit"] != null)
                                            rows_table_limit = obj2int32(node2.Attributes["rows_table_limit"].Value);
                                        

                                        if (node2.Attributes["x"] != null)
                                            x1 = obj2int32(node2.Attributes["x"].Value);
                                        if (node2.Attributes["y"] != null)
                                        {
                                            y1 = (int)PPage.PTable.eval_table_position(table_positions,
                                                node2.Attributes["y"].Value.ToString());
                                            //y1 = obj2int32(node2.Attributes["y"].Value);
                                        }

                                        if (node2.Attributes["name"] != null)
                                            table_name = obj2str(node2.Attributes["name"].Value);


                                        if (node2.Attributes["font"] != null)
                                            font = obj2int32(node2.Attributes["font"].Value);
                                        if (font <= 0) font = 12;
                                        PPage.PTable tabl = new PPage.PTable();
                                        tabl.font_size_4_table = font;
                                        tabl.start_point_4_table = new Point(x1, y1);
                                        Dictionary<long, string> header_names = new Dictionary<long, string>();
                                        //Dictionary< string ,  >

                                        foreach (XmlNode node3 in node2.ChildNodes)
                                        {
                                            switch (node3.Name)
                                            {
                                                #region SQL
                                                case "SQL":
                                                    try
                                                    {

                                                        #region ЗАГОЛОВКИ 
                                                        foreach (XmlNode node4 in node3.ChildNodes)
                                                        {


                                                            #region  ПОЛЕ
                                                            if (node4.Name == "FIELD")
                                                            {
                                                                
                                                                string summarize = "";
                                                                string align = "" ;
                                                                string style = "";
                                                                long font11 = 0;
                                                                if (node4.Attributes["summ"] != null)
                                                                    summarize = obj2str(node4.Attributes["summ"].Value);


                                                                string field_type = "", field_name = "", field_show = "";
                                                                long field_width = 0;
                                                                if (node4.Attributes["type"] != null)
                                                                    field_type = obj2str(node4.Attributes["type"].Value);

                                                                if (node4.Attributes["name"] != null)
                                                                    field_name = obj2str(node4.Attributes["name"].Value);

                                                                if (node4.Attributes["style"] != null)
                                                                    style = obj2str(node4.Attributes["style"].Value);

                                                                if (node4.Attributes["font"] != null)
                                                                    font11 = obj2int32(node4.Attributes["font"].Value);

                                                                if (node4.Attributes["align"] != null)
                                                                    align = obj2str(node4.Attributes["align"].Value);

                                                                if (node4.Attributes["show"] != null)
                                                                    field_show = obj2str(node4.Attributes["show"].Value);

                                                                if (field_show == "") field_show = field_name;
                                                                if (node4.Attributes["width"] != null)
                                                                    field_width = obj2int32(node4.Attributes["width"].Value);
                                                                Dictionary<string, string> h4 = new Dictionary<string, string>();
                                                                h4["type"] = field_type;
                                                                h4["width"] = field_width.ToString();
                                                                h4["show"] = field_show;
                                                                h4["summarize"] = summarize;
                                                                h4["font"] = font11.ToString();
                                                                h4["align"] = align.ToString();
                                                                h4["style"] = style.ToString();
                                                                
                                                                field_parameters[field_name] = h4;
                                                                field_parameters[field_name.ToUpper()] = h4;
                                                                //-----------
                                                                foreach (XmlNode node5 in node4.ChildNodes)
                                                                {
                                                                    #region IF
                                                                    if (node5.Name == "IF")
                                                                    {
                                                                        string condition = field_name;
                                                                        if (!conditions.ContainsKey(field_name))
                                                                        {
                                                                            conditions.Add(field_name, new Dictionary<string, XmlNode>());
                                                                        }

                                                                        if (node5.Attributes["condition"] != null)
                                                                            condition =  obj2str(node5.Attributes["condition"].Value);

                                                                        if (!conditions[field_name].ContainsKey(condition))
                                                                        {
                                                                            conditions[field_name].Add(condition , node5)   ;
                                                                        }
                                                                        else { 
                                                                            conditions[field_name][condition] = node5;
                                                                        }
                                                                        

                                                                    }
                                                                    #endregion
                                                                }
                                                                //-----------
                                                            }
                                                            #endregion 
                                                        }
                                                        #endregion 


                                                        string strSQL = node3.InnerText;
                                                        OracleCommand ora_com8 = new OracleCommand();
                                                        ora_com8.Connection = get_wms_connection();
                                                        ora_com8.CommandText = strSQL;
                                                        OracleDataReader ora_read = ora_com8.ExecuteReader();
                                                        long rows_count_read = 0;
                                                        long rows_count_limit = 1000;
                                                        if (node3.Attributes["limit"] != null)
                                                            rows_count_limit = obj2int32(node3.Attributes["limit"].Value);
                                                        long count_of_fields = 0;
                                                        long rows_count_read_in_page=0;
                                                        while (ora_read.Read() && rows_count_read < rows_count_limit)
                                                        {
                                                            rows_count_read++;
                                                            rows_count_read_in_page++;

                                                            #region СОЗДАНИЕ ТАБЛИЦЫ
                                                            if (count_of_fields == 0 || (rows_table_limit > 0 && rows_count_read_in_page > rows_table_limit))
                                                            {
                                                                // conditions[field_name][condition] = node5.InnerXml;    
                                                                #region ЕСЛИ ПЕРЕХОД СТРАНИЦЫ 
                                                                if (rows_table_limit > 0 && rows_count_read_in_page > rows_table_limit)
                                                                {
                                                                    List<PPage.PLabel> tmp_l = new List<PPage.PLabel>();
                                                                    foreach (PPage.PLabel i in _p.labels)
                                                                        if (i.repeat) tmp_l.Add( i.clone() );

                                                                    List<PPage.PArrow> tmp_a = new List<PPage.PArrow>();
                                                                    foreach (PPage.PArrow i in _p.arrows)
                                                                        if (i.repeat) tmp_a.Add(i);

                                                                    rows_count_read_in_page = 0;
                                                                    _p.tables.Add(tabl);
                                                                    PPages.Add(_p);
                                                                     
                                                                    tabl = new PPage.PTable();
                                                                    tabl.font_size_4_table = font;
                                                                    
                                                                    //Dictionary<long, string> header_names = new Dictionary<long, string>();
                                                                        
                                                                    if (node2.Attributes["xrepeat"] != null)
                                                                        x1 = obj2int32(node2.Attributes["xrepeat"].Value);
                                                                        
                                                                    if (node2.Attributes["yrepeat"] != null)
                                                                    {
                                                                        y1 = (int)PPage.PTable.eval_table_position(table_positions,
                                                                            node2.Attributes["yrepeat"].Value.ToString());
                                                                        //y1 = obj2int32(node2.Attributes["y"].Value);
                                                                    }
                                                                    tabl.start_point_4_table = new Point(x1, y1);


                                                                    _p = new PPage();
                                                                    _p.labels = tmp_l;
                                                                    _p.arrows = tmp_a;
                                                                    if (node.Attributes["axes"] != null)
                                                                        if (node.Attributes["axes"].Value.ToString() == "1")
                                                                            _p.print_axes();

                                                                    if (node.Attributes["landscape"] != null)
                                                                    {
                                                                        if (obj2int(node.Attributes["landscape"].Value) == 1)
                                                                            _p.Landscape = 1;

                                                                        if (obj2int(node.Attributes["landscape"].Value) == 0)
                                                                            _p.Landscape = 0;

                                                                    }


                                                                }
                                                                #endregion

                                                                count_of_fields = ora_read.VisibleFieldCount;

                                                                for (int i = 0; i < count_of_fields; i++)
                                                                {
                                                                    string field_name = ora_read.GetName(i);

                                                                    PPage.PColumn col;
                                                                    if (field_parameters.ContainsKey(field_name))
                                                                    {
                                                                        long c_column_width = 0, c_column_font=0; string c_column_type = "", c_column_show = "" , c_align="left" , c_style="" ;
                                                                        c_column_width = obj2int32(field_parameters[field_name]["width"]);
                                                                        c_column_type = obj2str(field_parameters[field_name]["type"]);
                                                                        c_column_show = obj2str(field_parameters[field_name]["show"]);
                                                                        c_column_font = obj2int32(field_parameters[field_name]["font"]);
                                                                        c_align = obj2str(field_parameters[field_name]["align"]);
                                                                        c_style= obj2str(field_parameters[field_name]["style"]);

                                                                        col = new PPage.PColumn(field_name, c_column_type, c_column_show, c_column_width, c_column_font);
                                                                        col.align = c_align;
                                                                        col.style = c_style;
                                                                    }
                                                                    else
                                                                    {
                                                                        col = new PPage.PColumn(field_name, "string", field_name);
                                                                    }


                                                                    //col = new PPage.PColumn(field_name, "string", field_name);
                                                                    tabl.columns.Add(col);
                                                                    header_names[i] = field_name;
                                                                }
                                                            }
                                                            #endregion

                                                            #region СТРОКА ТАБЛИЦЫ

                                                            Dictionary<string, string> _row2 = new Dictionary<string, string>();
                                                            for (int i = 0; i < count_of_fields; i++)
                                                            {
                                                                string val1 = "";
                                                                try
                                                                {

                                                                   bool _summarize=false;
                                                                    val1 = obj2str(ora_read.GetValue(i));
                                                                   if (field_parameters.ContainsKey(header_names[i]))
                                                                   if (field_parameters[(header_names[i])].ContainsKey("summarize"))   //["summarize"]    
                                                                        {
                                                                            if (field_parameters[(header_names[i])]["summarize"] == "1")
                                                                            {
                                                                                _summarize = true;
                                                                            }
                                                                        }


                                                                    
                                                                    if (_summarize)
                                                                        if (obj2double(val1) > 0)
                                                                        {

                                                                            string key_name = "[" + table_name + "." + header_names[i] + ".sum]";
                                                                            if (m_local_variables.ContainsKey(key_name))
                                                                            {
                                                                                m_local_variables[key_name] = (m_local_variables[key_name]) + obj2double(val1);
                                                                            }
                                                                            else
                                                                            {
                                                                                m_local_variables[key_name] = obj2double(val1);
                                                                            }
                                                                        

                                                                        }

                                                                }
                                                                catch { }

                                                                _row2[header_names[i]] = (val1);
                                                               

                                                            }
                                                            tabl.add_row(_row2);
                                                            #endregion
                                                            // Теперь заводим условия 
                                                            // conditions
                                                            // conditions[field_name][condition] = node5.InnerXml;
                                                            #region  обрабатываем условия ...
                                                            foreach ( string l_header_ in _row2.Keys )
                                                            {
                                                                if( conditions.ContainsKey( l_header_ ) ){
                                                                    foreach (string cond in conditions[l_header_].Keys)
                                                                    {
                                                                        if (PPage.PTable.eval_bool_cond(cond, _row2))
                                                                        {
                                                                            XmlNode xml1 = conditions[l_header_][cond];
                                                                            foreach (XmlNode chld in xml1.ChildNodes)
                                                                            {
                                                                                if (chld.Name == "BOXES")
                                                                                { // width='100' height='50' count='kor' 
                                                                                    int chld_width = obj2int32(chld.Attributes["width"].Value);
                                                                                    int chld_height = obj2int32(chld.Attributes["height"].Value);
                                                                                    string chld_count = chld.Attributes["count"].Value;
                                                                                    int padding_ = 3;
                                                                                    if( chld.Attributes["padding"] !=null )
                                                                                       padding_= obj2int32(chld.Attributes["padding"].Value);

                                                                                    int ylimit = 700;
                                                                                    if (chld.Attributes["ylimit"] != null)
                                                                                        ylimit = obj2int32(chld.Attributes["ylimit"].Value);


                                                                                    foreach( string _r in _row2.Keys )
                                                                                        chld_count=chld_count.Replace( "["+ _r +"]" , _row2[_r] );
                                                                                    for (int iii = 0; iii < obj2int32(chld_count); iii++)
                                                                                    {
                                                                                        tabl.add_box(new Point(chld_width, chld_height), padding_ , ylimit );
                                                                                    }
                                                                                }
                                                                            }
                                                                        }
                                                                    }
                                                               
                                                                }
                                                            }
                                                            #endregion 

                                                        }

                                                    }
                                                    catch (Exception ex)
                                                    {
                                                        MessageBox.Show(ex.Message);
                                                    }
                                                    break;
                                                #endregion

                                                #region ЗАГОЛОВОК ТАБЛИЦЫ
                                                case "HEAD":
                                                    long th_width = 0;
                                                    long th_height = 0;
                                                    string th_name = "";
                                                    string th_value = "";
                                                    string th_type = "string";
                                                    long count_of_th = 0;
                                                    foreach (XmlNode node4 in node3.ChildNodes)
                                                    {
                                                        if (node4.Name == "TH")
                                                        {
                                                            th_value = "";
                                                            th_name = "";
                                                            th_type = "string";

                                                            count_of_th++;
                                                            if (node4.Attributes["width"] != null)
                                                                th_width = obj2int32(node4.Attributes["width"].Value);

                                                            if (node4.Attributes["height"] != null)
                                                                th_height = obj2int32(node4.Attributes["height"].Value);

                                                            if (node4.Attributes["name"] != null)
                                                                th_name = obj2str(node4.Attributes["name"].Value);

                                                            if (node4.Attributes["type"] != null)
                                                                th_type = obj2str(node4.Attributes["type"].Value);

                                                            if (node4.InnerText != null)
                                                                th_value = obj2str(node4.InnerText);

                                                            if (th_name == "")
                                                                th_name = th_value;
                                                            if (th_name == "")
                                                                th_name = count_of_th.ToString();

                                                            PPage.PColumn col;
                                                            col = new PPage.PColumn(th_name, th_type, th_value, th_width);
                                                            tabl.columns.Add(col);
                                                            //tabl.add_column( th_name , th_type , 
                                                            header_names[count_of_th] = th_name;
                                                            //width type

                                                        }
                                                    }

                                                    break;
                                                #endregion
                                                case "TR":
                                                    #region СТРОКА ТАБЛИЦЫ
                                                    long count_of_td = 0;
                                                    Dictionary<string, string> _row = new Dictionary<string, string>();
                                                    foreach (XmlNode node4 in node3.ChildNodes)
                                                    {
                                                        
                                                        if (node4.Name == "TD")
                                                        {
                                                            string val = node4.InnerText;
                                                            val = Replace(val , m_local_variables );
                                                            if (header_names.ContainsKey(count_of_td))
                                                            {
                                                                string name = header_names[count_of_td];
                                                                _row[name] = val;
                                                            }
                                                            
                                                            

                                                        }
                                                        count_of_td++;
                                                    }
                                                    tabl.add_row(_row);
                                                    #endregion
                                                    break;
                                                default:
                                                    MessageBox.Show("Не известный ТЭГ " + node3.Name);
                                                    break;
                                            }

                                        }

                                        table_positions[table_name] = tabl.table_height() + y1;
                                        _p.tables.Add(tabl);



                                    }
                                    catch (Exception ex)
                                    {
                                        MessageBox.Show( "TABLE:"+ ex.Message);
                                    }



                                    break;
                                #endregion

                                default:
                                    MessageBox.Show("Не известный тег " + node2.Name);
                                    break;
                            }

                        }
                        PPages.Add(_p);
                    } // PAGE 

                } // 



                
              //  doc.ChildNodes[0].OuterXml();

            }
