        private void Тип_артикула_TextChanged(object sender, EventArgs e)
        {

            if (dataGridView11.CurrentRow == null)
                return;

            string art = obj2str(dataGridView11.CurrentRow.Cells[0].Value);
            long current_type_w = obj2int(dataGridView11.CurrentRow.Cells[18].Value);

            if (art == "") return;

            long new_type_w = obj2int(Тип_артикула.Text);

            if (current_type_w == new_type_w) return;

            if (new_type_w == 0 || new_type_w == 1 || new_type_w == 7 )// Тип товара = Штучный без модификации
            {
                // проверяем модификации товара -  сколько активных модификаций. если не  0 -то ругаемся.
                long cc = obj2int(get_wms_sql_result_single("select count(ID) from RABAEV.RRL_ARTICUL_MODS where ARTICUL='" + art +
                    "' and DELETED=0 "));

                if (cc > 0 && new_type_w == 0)
                {
                    MessageBox.Show("Для типа 0 необходимо отключить активные модификации. ");
                    return;
                }

                if (cc <= 0 && new_type_w == 1)
                {
                    MessageBox.Show("Для типа 1 необходимо создать активные модификации. ");
                    return;
                }

                if (cc <= 0 && new_type_w == 7)
                {
                    MessageBox.Show("Для типа 7 необходимо создать активные модификации. ");
                    return;
                }

            }

            ExecuteOracleNonQuery("update RABAEV.RRL_ARTICULS set type_w=" + new_type_w.ToString() + " where  ACTICUL='" + art + "' ");
            dataGridView11.CurrentRow.Cells[18].Value = new_type_w;

        }

        private void dataGrid_pallets_CellFormatting(object sender, DataGridViewCellFormattingEventArgs e)
        {



            if (e.ColumnIndex == 0)
            {
                if (dataGrid_pallets[15, e.RowIndex].Value != null)
                {
                    long type_w = obj2int(dataGrid_pallets[15, e.RowIndex].Value);
                    switch (type_w)
                    {
                        case 0:
                            e.CellStyle.BackColor = Color.AliceBlue;
                            break;

                        case 1:
                            e.CellStyle.BackColor = Color.Aqua;
                            break;

                        case 2:
                            e.CellStyle.BackColor = Color.Green;
                            break;

                        case 3:
                            e.CellStyle.BackColor = Color.LemonChiffon;
                            break;
                        case 5:
                            e.CellStyle.BackColor = Color.LightSeaGreen;
                            break;
                        case 6:
                            e.CellStyle.BackColor = Color.Blue;
                            break;

                        default:
                            break;
                    }



                }
            }


        }

