        private void button3_Click(object sender, EventArgs e)
        {
            
            if (dataGridView22.CurrentRow == null)
            {
                return;
            }
            string PUID = obj2str(dataGridView22.CurrentRow.Cells[1].Value);
            if (PUID == "") { return; }
            string ret = wms_get_spfunction_value("REMAINS.OTHOD_PALLET_PODBOR_PARTII", "PALLET_ID1", PUID);

            object o = dataGridView22.CurrentRow.Cells[1].Value;

            string strSQL = "select  ARTICUL ,  ID  , PRIHOD_PALLET_UID , current_mod_id from RABAEV.RRL_SBORKA_PALLET_ROWS R " +
            " where PALLET_UID='" + o.ToString() + "' order by SORTFIELD ";
            OracleCommand ora_com= new OracleCommand();
            ora_com.Connection= get_wms_connection();
            ora_com.CommandText = strSQL;
            OracleDataReader ora_read = ora_com.ExecuteReader();
            Dictionary<string, string> dic = new Dictionary<string, string>();
            Dictionary<string, string> mod_dic = new Dictionary<string, string>();
            while (ora_read.Read())
            {
                dic[ obj2str( ora_read.GetValue(1))] = obj2str( ora_read.GetValue(2));
                mod_dic[obj2str(ora_read.GetValue(1))] = obj2str(ora_read.GetValue(3));
            }

            foreach( DataGridViewRow dr in  dataGridView23.Rows  )
            {
                if (dr.Cells[3].Value != null)
                {
                    if (dic.ContainsKey(dr.Cells[3].Value.ToString()))
                    {
                        dr.Cells[10].Value = dic[dr.Cells[3].Value.ToString()];
                        dr.Cells[7].Value = mod_dic[dr.Cells[3].Value.ToString()];
                    }
                }
            }
            

            dataGridView23_CellEnter(null, null);

        }

