        private void загрузкаМодификацийИзExcelToolStripMenuItem_Click(object sender, EventArgs e)
        {
       
            MessageBox.Show("Загрузка справочника модификаций из файла C:\\WMS\\mods.xls \r\n " +
                "формат: ID , артикул, название,штук_в_кор, вес_шт , вес_картона , шк_шт, шк_кор , тип  ");
            long pos = 2;
            long poceed = 0;
            try
            {
                //Excel Application Object
                Excel.Application oExcelApp = new Excel.Application();
                oExcelApp.Visible = true;

                object obj = new object();
                string Filename = "C:\\WMS\\mods.xls";


                oExcelApp.Workbooks.Open(Filename, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing, Type.Missing);


                while (obj2str(((Excel.Range)oExcelApp.Cells[pos, 2]).Value2) != "")
                {

                    int ID = obj2int32(((Excel.Range)oExcelApp.Cells[pos, 1]).Value2);
                    string articul = ((Excel.Range)oExcelApp.Cells[pos, 2]).Value2.ToString();
                    string Name = ((Excel.Range)oExcelApp.Cells[pos, 3]).Value2.ToString();
                    double sht_in_kor = obj2double(((Excel.Range)oExcelApp.Cells[pos, 4]).Value2);
                    double ves_sht = obj2double(((Excel.Range)oExcelApp.Cells[pos, 5]).Value2);
                    double ves_kart_kor = obj2double(((Excel.Range)oExcelApp.Cells[pos, 6]).Value2);
                    string SHK_SHT = obj2str(((Excel.Range)oExcelApp.Cells[pos, 7]).Value2);
                    string SHK_KOR = obj2str(((Excel.Range)oExcelApp.Cells[pos, 8]).Value2);
                    int type1 = obj2int32(((Excel.Range)oExcelApp.Cells[pos, 9]).Value2);

                    if (articul != "" && Name != "" && sht_in_kor > 0 && ves_sht > 0 && ves_kart_kor > 0)
                    {
                        OracleCommand ora_com = new OracleCommand();
                        ora_com.Connection = get_wms_connection();
                        ora_com.CommandText = "RABAEV.UPDATE_RRL_MOD2";
                        ora_com.CommandType = CommandType.StoredProcedure;

                        ora_com.Parameters.Add("ID1", OracleType.Int32).Value = ID;
                        ora_com.Parameters.Add("ARTICUL1", OracleType.VarChar).Value = articul;
                        ora_com.Parameters.Add("NAME1", OracleType.VarChar).Value = Name;
                        ora_com.Parameters.Add("SHT_IN_KOR1", OracleType.Number).Value = sht_in_kor;
                        ora_com.Parameters.Add("SHT_WEIGHT1", OracleType.Number).Value = ves_sht;
                        ora_com.Parameters.Add("KARTON_WEIGHT1", OracleType.Number).Value = ves_kart_kor;
                        ora_com.Parameters.Add("DELETED1", OracleType.Int32).Value = 0;

                        ora_com.Parameters.Add("SHK_SHT1", OracleType.VarChar).Value = SHK_SHT;
                        ora_com.Parameters.Add("SHK_KOR1", OracleType.VarChar).Value = SHK_KOR;

                        ora_com.Parameters.Add("ID", OracleType.Int32).Direction = ParameterDirection.ReturnValue;
                        ora_com.ExecuteNonQuery();
                        if (ID == 0)
                        {
                            ID = obj2int32(ora_com.Parameters["ID"].Value);
                            ((Excel.Range)oExcelApp.Cells[pos, 1]).Value2 = ID;
                        }
                        if (type1 >= 0)
                        {
                            ExecuteOracleNonQuery(" update RABAEV.RRL_ARTICULS set TYPE_W=" + type1.ToString() + " where ACTICUL='" + articul + "' ");
                        }
                        poceed++;
                    }

                    pos++;
                }

                MessageBox.Show(" Процедура закончена из " + pos.ToString() + " закачано строк " + poceed.ToString());
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
            }

        }





