        private void печатьБольшихШтрихКодовToolStripMenuItem_Click(object sender, EventArgs e)
        {
            string strXML = "<PAGE>";
            int count_in_page = 5;
            int count_done = 0;
            int step = 270;
            int rem = 0;
            foreach (DataGridViewRow dr in dataGridView8.Rows)
            {
                if (Convert.ToBoolean(dr.Cells[0].Value))
                {
                    count_done++;
                    string cell = dr.Cells[1].Value.ToString();
                    bool otborr = Convert.ToBoolean(dr.Cells[2].Value);
                    rem=count_done % count_in_page;
                    string ttt = "";
                    if (otborr)
                    {
                        ttt = cell + "  ОТБ";
                    }
                    else {
                        ttt = cell;
                    }

                    if ((rem) == 0) 
                    {
                        count_done = 1;
                        strXML = strXML + "</PAGE><PAGE>";
                    }

                    if ((rem) == 1)
                    {
                    //    strXML = strXML + "<PAGE>";
                    }

                    strXML = strXML+"<LABEL fontsize='24'   x='50'   y='" +obj2str(50+(count_done-1)*step)+  "' type='EAN3'  width='600'  height='150'   > "+cell+" </LABEL> "+
                    "<LABEL fontsize='52'   x='100'   y='" + obj2str(220 + (count_done - 1) * step) + "'    width='600'  height='150'   >" + ttt + "</LABEL>" +
                    "<RECT   x1='50'  y1='" + obj2str(20 + (count_done - 1) * step) + "'  x2='600'  y2='" + obj2str(280 + (count_done - 1) * step) + "' fill='0' ></RECT>";

                    
                }
            }

            
                strXML = strXML + "</PAGE>";

                strXML = strXML.Replace("<PAGE></PAGE>", "");

            strXML = "<BODY>" + strXML + "</BODY>";

            Dictionary<string, Dictionary<string, string>> database = new Dictionary<string, Dictionary<string, string>>();
            Dictionary<string, string> constants = new Dictionary<string, string>();

            PrintFromXML(strXML, database, constants);

        }

