        private List<Dictionary<string, object>> СравнитьОстаткиСМСОстаткамиWMS( List<string>  arts , int ware_id1 )
        {

            Dictionary<string, string> names= new Dictionary<string,string>();

            string arts7 = "";

            foreach (string a in arts)
            {
                arts7 = arts7 + ", '" + a + "' ";
            }
            arts7 = arts7.Trim(',');
             string strSQL = " select g.article, g.quantity  ,         "+        
             " g.quantity-g.reservedquantity-g.incomingquantity+g.foundquantity  , "+
             " g.reservedquantity , g.incomingquantity , g.foundquantity , c.shortname  " +
             " from supermag.smgoods g , supermag.smcard c " +
             " where  c.article =g.article  and  g.storeloc = " + CachedQuerySingle("select value from RRL_CONSTANTS where name='storeloc' ") + " and g.article in ( " + arts7 + " ) ";
             

            OracleCommand ora_com = new OracleCommand();
            OracleConnection ora_conn = new OracleConnection();
            ora_conn.ConnectionString = SM_CONNECTION_STRING();
            ora_conn.Open();
            ora_com.Connection = ora_conn;
            ora_com.CommandText = strSQL;
            OracleDataReader ora_reader = ora_com.ExecuteReader();
            Dictionary<string, List<object>> sm_nakl = new Dictionary<string, List<object>>();
            
            while (ora_reader.Read())
            {
                List<object> o = new List<object>();
                o.Add(ora_reader.GetValue(1));
                o.Add(ora_reader.GetValue(2));
                o.Add(ora_reader.GetValue(3));
                o.Add(ora_reader.GetValue(4));
                o.Add(ora_reader.GetValue(5));
                names[ora_reader.GetValue(0).ToString()] = obj2str(ora_reader.GetValue(6));
                // sm_nakl[ora_reader.GetValue(0).ToString()] = new PointF(obj2float(ora_reader.GetValue(1)), obj2float(ora_reader.GetValue(2)));
                sm_nakl[ora_reader.GetValue(0).ToString()] = o;
            }

            ora_reader.Close();
            ora_reader.Dispose();
            ora_reader = null;
            if (sm_nakl.Count == 0)
            {
                return null;
            }
            string str66 = "";
            if (ware_id1 > 0 )
            {
                str66 = " and cel.ware_id=" + ware_id1.ToString()+ " ";
            }

            string strSQL2 = " select pal.articul , sum( rr.remain ) , art.name , "+
                " ORDERS.get_unfinished_quantity(  pal.articul , systimestamp-2 ) ,  "+
                " ORDERS.get_unfinished_quantityo(  pal.articul , systimestamp-2 )   " + 
                " from " +
                " rrl_remains rr , rrl_pallets pal , rrl_cells cel , rrl_articuls art "+
                " where art.acticul = pal.articul  and  " +
                " rr.cell=cel.cell and rr.UID_POLETA = pal.UID_PALLET   " + str66 +
                " and pal.articul in ( " + arts7 + " ) and cel.BLOCKED_FOR_REMAINS=0 "+
                " group by  pal.articul ,  art.name ";

            OracleCommand ora_com2 = new OracleCommand();
            ora_com2.Connection = get_wms_connection();
            ora_com2.CommandText = strSQL2;
            OracleDataReader ora_read2 = ora_com2.ExecuteReader();

            Dictionary<string, double> wms_nakl = new Dictionary<string, double>();
            Dictionary<string, double> wms_reserv = new Dictionary<string, double>();
            Dictionary<string, double> wms_reservO = new Dictionary<string, double>();
            while (ora_read2.Read())
            {
                wms_nakl[ora_read2.GetValue(0).ToString()] = Convert.ToDouble(ora_read2.GetValue(1));
                names[ora_read2.GetValue(0).ToString()] = obj2str(ora_read2.GetValue(2));
                wms_reserv[ora_read2.GetValue(0).ToString()] = Convert.ToDouble(ora_read2.GetValue(3));
                wms_reservO[ora_read2.GetValue(0).ToString()] = Convert.ToDouble(ora_read2.GetValue(4));
            }

            ora_read2.Close();
            ora_read2.Dispose();
            ora_read2 = null;
            List<Dictionary<string, object>> res = new List<Dictionary<string, object>>();

            foreach (string art_in_wms in wms_nakl.Keys)
            {
                Dictionary<string, object> result_row = new Dictionary<string, object>();
                if (sm_nakl.ContainsKey(art_in_wms))
                {
                    
                        
                        result_row["articul"] = art_in_wms;
                        result_row["count_in_wms"] = wms_nakl[art_in_wms];
                        result_row["count_in_sm"] = sm_nakl[art_in_wms][0];
                        result_row["count_in_sm_dost"] = sm_nakl[art_in_wms][1];
                        result_row["РЕЗЕРВ"] = sm_nakl[art_in_wms][2];
                        result_row["ВПути"] = sm_nakl[art_in_wms][3];
                        result_row["ПотериОбнаружения"] = sm_nakl[art_in_wms][4];
                        result_row["ЦенаТовара"] = obj2double(get_wms_sql_result_single("select LAST_PRICE from rrl_articuls where acticul='" + art_in_wms + "'"));
                        result_row["ССП"] = obj2double(get_wms_sql_result_single("select SSP from rrl_articuls where acticul='" + art_in_wms + "'"));

                        result_row["NU"] = obj2double(get_wms_sql_result_single("select NORMA_UKLADKI from rrl_articuls where acticul='" + art_in_wms + "'"));


                        /*g.quantity  ,         "+        
                 " g.quantity-g.reservedquantity-g.incomingquantity+g.foundquantity  , "+
                 " g.reservedquantity , g.incomingquantity , g.foundquantity */

                        result_row["name"] = "";
                        if(names.ContainsKey( art_in_wms ))
                            result_row["name"] = names[art_in_wms];

                        result_row["РезервWMS"] = 0;
                        if (wms_reserv.ContainsKey(art_in_wms))
                        {
                            result_row["РезервWMS"] = wms_reserv[art_in_wms];
                            result_row["Резерв_по_заказам"] = wms_reservO[art_in_wms];
                        }

                    

                        //result_row["ST"] = ST;
                        res.Add(result_row);
                    
                    sm_nakl.Remove(art_in_wms);
                }
                else
                { // Фиксируем отсутствие артикула в супермаге

                    result_row["articul"] = art_in_wms;
                    result_row["count_in_wms"] = wms_nakl[art_in_wms];
                    result_row["count_in_sm"] = 0;
                    result_row["count_in_sm_dost"] = 0;
                    result_row["РЕЗЕРВ"] = 0;
                    result_row["ВПути"] = 0;
                    result_row["ПотериОбнаружения"] = 0;
                    result_row["ЦенаТовара"] = obj2double(get_wms_sql_result_single("select LAST_PRICE from rrl_articuls where acticul='" + art_in_wms + "'"));
                    result_row["ССП"] = obj2double(get_wms_sql_result_single("select SSP from rrl_articuls where acticul='" + art_in_wms + "'"));
                    result_row["NU"] = obj2double(get_wms_sql_result_single("select NORMA_UKLADKI from rrl_articuls where acticul='" + art_in_wms + "'"));

                    result_row["name"] = "";
                    if (names.ContainsKey(art_in_wms))
                        result_row["name"] = names[art_in_wms];

                    result_row["РезервWMS"] = 0;
                    if (wms_reserv.ContainsKey(art_in_wms))
                    {
                        result_row["РезервWMS"] = wms_reserv[art_in_wms];
                        result_row["Резерв_по_заказам"] = wms_reservO[art_in_wms];
                    }
                    //result_row["ST"] = ST;
                    res.Add(result_row);
                }

            }

            foreach (string kk in sm_nakl.Keys)
            {
               
                    Dictionary<string, object> result_row = new Dictionary<string, object>();
                    result_row["articul"] = kk;
                    result_row["count_in_wms"] = 0;

                    result_row["count_in_sm"] = sm_nakl[kk][0];
