        private void подгрузитьЛогопараметрыТовараToolStripMenuItem_Click(object sender, EventArgs e)
        {

                       
            Dictionary<string, string> СписокПАЛ = new Dictionary<string, string>();
            List<Dictionary<string, object>> res2 = new List<Dictionary<string, object>>();
            string sq="";
             
            foreach (DataGridViewRow dr in dataGridView2.Rows)
            {
                    try
                    {
                        if (Convert.ToBoolean(dr.Cells[0].Value))
                        {
                            string PAL_NUMBER = dr.Cells[4].Value.ToString();
                            if (!СписокПАЛ.ContainsKey(PAL_NUMBER))
                            {
                                СписокПАЛ[PAL_NUMBER] = PAL_NUMBER;
                                sq = sq + " '" + PAL_NUMBER + "' ,";
                            }
                        }
                    }
                    catch
                    { }

             }
             sq = sq.Trim(',');
             if (sq == "")
             {
                 return;
             }
             string sqwl = " select DISTINCT RW.ARTICUL , PAL.ware_id from "+
                 " RABAEV.RRL_SBORKA_PALLET_ROWS RW , RABAEV.RRL_SBORKA_PALLETS PAL "+
                 " where  RW.PALLET_UID = PAL.PALLET_UID and  PAL.PALLET_UID in (" + sq + ")  ";

             OracleCommand ora_com = new OracleCommand();
             ora_com.Connection = get_wms_connection();
             ora_com.CommandText = sqwl;
             int i = 0;
             OracleDataReader ora_read = ora_com.ExecuteReader();
             while (ora_read.Read())
             {
                 i++;
                 string art = ora_read.GetString(0);
                 long ware_id = obj2int( ora_read.GetValue(1));
                 SyncArticul( art, ware_id );
             
             }


             string sqwl2 = " select DISTINCT RW.ARTICUL , PAL.ware_id , ART.CELL from " +
             " RABAEV.RRL_SBORKA_PALLET_ROWS RW , RABAEV.RRL_SBORKA_PALLETS PAL , RRL_ARTICULS ART " +
             " where  RW.PALLET_UID = PAL.PALLET_UID and  PAL.PALLET_UID in (" + sq + ") and ART.ACTICUL = RW.ARTICUL ";



             ShowQuery(sqwl2, "Подгруженные Артикулы" );


        }

