                    }
                }
                strSQL3 = strSQL3.Trim(',');

                strSQL3 = " and  ORD_NUMBER in (" + strSQL3 + ") ";

            }
            #endregion


            DateTime Дата_ст2 = new DateTime();
            Дата_ст2 = дата_ст.AddDays(1);
            Дата_ст2 = Дата_ст2.AddMinutes(-1);
