                str_where2 = " and PP.ADDR=adr.ADDR and adr.Region like '%" + Сборка_фильтр_регион.Text.Trim() + "%' ";
            }

            if (strSQL3.Trim() != "")
            {
                ware_sql = "";
                strSQL2 = "";
            }

            strSQL = " select 'false' ,  ORDS.ID , ORDS.ORD_NUMBER , ORDS.ADDR , ORDS.ORDDATE , ORDS.STATE , "+
                " ORDS.CREATE_DATE , ORDS.USER_ID , ORDS.COND ,   COMPL.order_vycherk_count(ORDS.ID) , COMPL.order_rows_count(ORDS.ID) , ords.ORD1  " +
            " from  RABAEV.RRL_ORDERS ORDS " + str2222 + " where (( ORDS.CREATE_DATE >= " + date2sql_ora(дата_ст) +
            " and ORDS.CREATE_DATE<= " + date2sql_ora(Дата_ст2) + " ) or ORDS.COND in (2,3,4,5)  ) " +
                strSQL2 + strSQL3 + ware_sql + str_where2 + " order by  ORDS.ADDR , ORDS.ware_id , ORDS.ID ";

            fill_view_MINI_WMS(dataGridView_orders, strSQL, 12);
        }

