        private void поделитьНаПаллетыToolStripMenuItem_Click(object sender, EventArgs e)
        {

            foreach (DataGridViewRow dr in dataGridView_orders.Rows)// По всем паллетам
            {
                try
                {
                    if (Convert.ToBoolean(dr.Cells[0].Value))
                    {
                        int CT_NUMBER = obj2int32(dr.Cells[1].Value);
                        string ORD_NUMBER = obj2str(dr.Cells[2].Value);

                        if (CT_NUMBER != 0)
                        {
                            int current_ware_id = obj2int32( CachedQuerySingle(" select max(ware_id) from RABAEV.RRL_ORDERS ORDS where ORDS.id='" + CT_NUMBER + "' ")); ;
                            if (current_ware_id <= 0) {
                                MessageBox.Show("Не удается определить склад для заказа '" + current_ware_id + "'");
                                return;
                            }

                            string DEVIDE_ROUTINE = CachedQuerySingle(" select DEVIDE_ROUTINE from rrl_wares where id=" + current_ware_id.ToString() + " ") ;
                            if ( DEVIDE_ROUTINE == "load_order_from_sm" || DEVIDE_ROUTINE == "split_vegetables"  )
                            {
                                bool mistake = false;
                                #region ДЕЛЕНИЕ НА ПАЛЛЕТЫ
                                Dictionary<string, object> values = new Dictionary<string, object>();

                                #region ПРОВЕРЯЕМ ЛОГОПАРАМЕТРЫ И КОРРЕКТНОСТЬ ВЫБРАННОГО СКЛАДА                               
                                int contains_invalid_logo= obj2int32( wms_get_spfunction_value("ORDERS.contains_invalid_logo" , "ord_number1" ,ORD_NUMBER ));
                                string wares= obj2str( wms_get_spfunction_value("ORDERS.wares_of_order", "ord_number1", ORD_NUMBER));

                                if (wares == "") {
                                    MessageBox.Show("Заказ " + ORD_NUMBER + "  не обеспечен товаром. Внимательно проверьте наличие товара. Исключите Заказ из списка. ");
                                    return;
                                }
                                
                                if (wares.IndexOf(',')!=-1)
                                {

                                    ShowQuery("    select rrl_skladname_by_id( cl.ware_id ) , rws.articul  from rrl_orders rd , rrl_order_rows   rws , "+
                                        "   rrl_articuls art , rrl_cells cl "+
                                        "       where rws.order_id=rd.id and rd.ord_number='" + ORD_NUMBER + "' " +
                                        "       and art.acticul=rws.articul and art.cell=cl.cell ", "Заказ содержит артикулы разных складов. Исправьте.");
                                    mistake = true;
                                    return;
                                }

                                if (contains_invalid_logo > 0)
                                {
                                    ShowQuery(" select rs.* from  RABAEV.RRL_ORDER_ROWS  rs , rrl_orders head where rs.order_id=head.id and quantity_planned>0 and head.ord_number='" + ORD_NUMBER + "' and ( obj2number( rs.tareweight)=0 or obj2number( rs.taresize )=0  )   ", "Заказ '" + CT_NUMBER + "' содержит артикулы с нулевыми логопараметрами");                              
                                    mistake = true;
                                    return;
                                }

                                if (wares.Trim() != obj2str(current_ware_id))
                                {
                                    MessageBox.Show("Склад заказа " + ORD_NUMBER + " (" + wares + ") не равен выбранному складу (" + obj2str(current_ware_id) + ") ");
                                    return;
                                }


                                #endregion

                                values["user_id1"] = wms_user.user_id;
                                values["ST_NUMBER1"] = ORD_NUMBER;
                                object ret3   = wms_get_spfunction_value2("ORDERS.DELETE_PALLETS", values, OracleType.VarChar, 255);


                                values = new Dictionary<string, object>();
                                values["ord_number1"] = ORD_NUMBER;
                                values["ware_id2"] = current_ware_id;

                                int ret99 = 0;

                                if (DEVIDE_ROUTINE == "split_vegetables")
                                {
                                    ret99 = obj2int32(wms_get_spfunction_value2("pall_splitter.split_vegetables", values, OracleType.Int32, 0));
                                    // Распределяем подобранные партиии по паллетам. 

                                }
                                else {
                                    ret99 = obj2int32(wms_get_spfunction_value2("pall_splitter.split_ufa", values, OracleType.Int32, 0));
                                }

                                if (ret99 == -1)
                                {
                                    MessageBox.Show("Заказ '" + CT_NUMBER + "' изменять нельзя " + "  ");
                                }

                                if (ret99 == -30)
                                {
                                    MessageBox.Show("Заказ '" + CT_NUMBER + "' содержит неизвестный порядок сборки.   ");
                                    return;
                                }

                                if (ret99 == -10)
                                {

                                    MessageBox.Show("Заказ '" + CT_NUMBER + "' не рассчитан. бесконечный цикл.   ");
                                    return;
                                }

                                if (ret99 == -20)
                                {
                                    MessageBox.Show("Заказ '" + CT_NUMBER + "' содержит артикулы с нулевыми логопараметрами.");
                                    ShowQuery(" select rs.* from  RABAEV.RRL_ORDER_ROWS  rs , rrl_orders head where rs.order_id=head.id and head.ord_number='" + CT_NUMBER + "' ", "Заказ '" + CT_NUMBER + "' содержит артикулы с нулевыми логопараметрами");
                                    return;
                                }

                                #endregion
                            }
                            else
                            {
                                #region ДЕЛЕНИЕ ОВОЩНОГО СКЛАДА.
                                Dictionary<string, object> values = new Dictionary<string, object>();
                                values["ord_id1"] = CT_NUMBER;
                                values["user_id11"] = wms_user.user_id;
                                object ret ; // = wms_get_spfunction_value2("COMPL.divide_order_bypal2", values, OracleType.Int32, 0);

                                values = new Dictionary<string, object>();
                                values["ord_number1"] = ORD_NUMBER;
                                values["ware_id2"] = current_ware_id;
                                ret = (wms_get_spfunction_value2("pall_splitter.split_vegetables", values, OracleType.Int32, 0));

                                if (obj2int32(ret) < 0)
                                {
                                    MessageBox.Show("ошибка в функции COMPL.divide_order_bypal2  ");
                                }
                                dr.Cells[8].Value = ret;
                                #endregion
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show(ex.Message);
                }
            }

        }

