                            List<object> objects = get_wms_sql_result_array(" select PALLET_UID from RABAEV.RRL_SBORKA_PALLETS where ST_NUMBER='" + CT_NUMBER + "'  ");
                                foreach (object o in objects)
                                {
                                    Dictionary<string, string> constants = new Dictionary<string, string>();
                                    constants["zakaz_id"] = o.ToString();
                                    constants["order_id"] = CT_NUMBER;
                                    if (!zakazes.ContainsKey(CT_NUMBER))
