        private void НомерСТКПодгрузке_KeyPress(object sender, KeyPressEventArgs e)
        {
            //textBox_Запрос.Text = textBox_Запрос.Text +"_"+ obj2str((int)e.KeyChar);
            if (e.KeyChar == '\r')
            {
                
                string Номер_wp = "";
                string klad_ = "";
                if (НомерСТКПодгрузке.Text.IndexOf('W') == -1) return;

                int i = Math.Min(НомерСТКПодгрузке.Text.IndexOf('K'), НомерСТКПодгрузке.Text.IndexOf('S'));
                if ( i > -1)
                {
                    if (НомерСТКПодгрузке.Text.IndexOf('W') < i )
                    {
                        Номер_wp = НомерСТКПодгрузке.Text.Substring(0, i );
                        klad_ = НомерСТКПодгрузке.Text.Substring(i, НомерСТКПодгрузке.Text.Length - i);
                    }
                    else {
                        klad_ = НомерСТКПодгрузке.Text.Substring(0, НомерСТКПодгрузке.Text.IndexOf('W') );
                        Номер_wp= НомерСТКПодгрузке.Text.Substring(НомерСТКПодгрузке.Text.IndexOf('W'), НомерСТКПодгрузке.Text.Length - НомерСТКПодгрузке.Text.IndexOf('W'));
                    }
                }
                else {
                    Номер_wp = НомерСТКПодгрузке.Text;
                }



                if (Номер_wp.IndexOf('W') != -1) // Если введен штрих-код сборочника
                {
                    string puid = pallet_uid_decode(Номер_wp);
                    string strSQL = " select ST_NUMBER from RABAEV.RRL_SBORKA_PALLETS where PALLET_UID='" + puid + "' ";
                    string ST_NUMBER = obj2str( get_wms_sql_result_single(strSQL));
                    НомерСТКПодгрузке.Text = ST_NUMBER;



                    if (puid != "" && klad_ != "")
                    {


                        Dictionary<string, object> values = new Dictionary<string, object>();
                        values["PALLET_UID1"] = puid;
                        values["SBORSHIK1"] = klad_;
                        values["user_id1"] = wms_user.user_id;
                        object ret = wms_get_spfunction_value2("COMPL.SET_SBORSHIK", values, OracleType.Int32, 0);


                    }

                    
                    
                    button34_Click(null,null);
                    foreach (DataGridViewRow rd in dataGridView22.Rows)
                    {
                        if (obj2str(rd.Cells[1].Value) == puid)
                        {
                            rd.Selected = true;
                        }
                    }
                    НомерСТКПодгрузке.Text = "";
                }
            }
        }

