        public string scanner_from_r(string str_from)
        {
            string str_R = "ЙЦУКЕНГШЩЗХЪФЫВАПРОЛДЖ"+ "ЯЧСМИТЬБЮ."; // "Э"+
            string str_U = "QWERTYUIOP{}ASDFGHJKL:"+"ZXCVBNM<>/"; // '"'+
            string str_to = "";
            for (int i = 0; i < str_from.Length; i++)
            {
                if (str_R.IndexOf(str_from[i]) != -1)
                {
                    str_to = str_to + str_U[str_R.IndexOf(str_from[i])];
                }
                else {
                    str_to = str_to + str_from[i];
                }
            }

            str_to.Replace("Э", "'");
            return str_to;
        }


        private void зафиксироватьСпрукПаллетВОтборToolStripMenuItem_Click(object sender, EventArgs e)
        {
           
            List<Dictionary<string, object>> result1 =  new List<Dictionary<string,object>>();


             string ret = ask("Отсканируйте паллеты и нажмите ОК" , "Отсканируйте паллеты" , "" , 0 );
             if (ret != "")
             {
                 ret=scanner_from_r(ret.ToUpper());
                 foreach (string s in ret.Split('P'))
                 {
                     if (s != "")
                     {
                         string s2 = "P"+ (s.Trim());
                         s2 = s2.Replace('?', 'Т');
                         s2 = s2.Replace(',', 'Т');

                         Dictionary<string, object> row1 = new Dictionary<string, object>();
                         #region  СПУСК ПАЛЛЕТА В ЕГО ЯЧЕЙКУ ОТБОРА
                         // function move_pall_2_picking_cell( pall_uid1 varchar2 , user_id2 varchar2 ) return varchar2 
                         Dictionary<string, object> values = new Dictionary<string, object>();
                         values["pall_uid1"] = s2.Trim();
                         values["user_id2"] = this.wms_user.user_id;

                         string ret2 = obj2str(wms_get_spfunction_value2("REMAINS.move_pall_2_picking_cell", values, OracleType.VarChar, 100));
                         row1["pall_uid"] = s2.Trim();
                         row1["result"] = ret2;
                         result1.Add(row1);
                         #endregion
                     }

                 }
                 ShowArray( result1 , "Перемещение паллет в отбор" );
             }
        }

