        private List<Dictionary<string, object>> Сравнить_приходные_накладные(List<string> articul_array, bool Сравнивать_по_ЗаказамОснованиям, DateTime Дата_движений_от, DateTime Дата_движений_до)
        {
            Dictionary<string, object[]> lines_SM = new Dictionary<string, object[]>();
            Dictionary<string, object[]> lines_WMS = new Dictionary<string, object[]>();
            Dictionary<string, object[]> lines_RESULT = new Dictionary<string, object[]>();
            Dictionary<string, string> Список_Артикулов = new Dictionary<string, string>();
            string sql1 = "";
            string strSQL = " select NAKLADNAME, ARTICUL , COUNT1 , DATE_OF_ACCEPT " +
             " from RABAEV.RRL_OTHOD_NAKLAD_ROWS r , RABAEV.RRL_OTHOD_NAKLAD h " +
             " where h.ID= r.ID_NAKLAD " +
             " and condition=2 and ware_id=" + this.wms_user.ware_id.ToString() + sql1;

            long pos4 = 0;
            OracleConnection ora_conn;
            OracleCommand ora_com;
            OracleDataReader ora_reader;
            ora_com = new OracleCommand();

            // Список_Артикулов
            #region ВЫДЕЛЕНИЕ СПИСКА АРТИКУЛОВ
            string SQL_IN = "";
            string SQL_IN2 = "";
            foreach (string sss in articul_array)
            {
                SQL_IN = SQL_IN + " '" + sss + "' ,";
            }
            SQL_IN = SQL_IN.Trim(',');
            if (SQL_IN=="")
            {

                return new List<Dictionary<string, object>>();
            }
            #endregion

            string str1 = "ZAKAZ_NUMBER";
            if ( Сравнивать_по_ЗаказамОснованиям )
            {
                str1 = "PRIHOD.order_zakaz_number( h.ID )";
            }
            else {
                str1 = "SM_NAKLAD_NUMBER";
            }

            strSQL = " select " + str1 + " , p.ARTICUL ,  sum( UNIT_COUNT) kol  " +
            " from RABAEV.RRL_PALLETS p , RABAEV.RRL_PRIHOD_NAKLAD h  " +
            " where  p.PRIHOD_NAKLAD_ID =  h.ID  " +
            " and condition=2 and DATE_OF_ACCEPT  between " +
            " to_date( " + date2sql_ora(Дата_движений_от) + " ,'dd.mm.yyyy') and to_date(" + date2sql_ora(Дата_движений_до) +
            ",'dd.mm.yyyy') and p.ARTICUL in (" + SQL_IN + ")  group by  " + str1 + "   , p.ARTICUL  ";// + sql3 
            string key = "";

            ora_com.CommandText = strSQL;
            long pos1 = 0;
                ora_com.Connection = get_wms_connection();
                ora_com.CommandText = strSQL;
                ora_reader = ora_com.ExecuteReader();

                while (ora_reader.Read())
                {
                    object[] values1 = new object[7];
                    for (int yy = 0; yy < 3; yy++)
                    {
                        values1[yy] = ora_reader.GetValue(yy).ToString();
                    }
                    key = values1[0].ToString().Trim().ToUpper() + "_" + values1[1].ToString().Trim();
                    lines_WMS[key] = new object[] { values1[0], values1[1], obj2double(values1[2]) } ;     
                    pos4++;
                }
                //MessageBox.Show("Сколичество движений по WMS = " + pos4.ToString());
                ora_reader.Close();
  
            // Сверка приходных накладных

                if (Сравнивать_по_ЗаказамОснованиям)
                {

                    strSQL = " SELECT baseid , s.article Артикул, " +
                   "  SUM(s.quantity) Колво " +
                   "  FROM supermag.smdocuments   d, " +
                   "  supermag.smspec        s, " +
                   "  supermag.smcommonbases osnov " +
                   "  WHERE d.doctype IN ('WI', 'IW') " +
                   "     AND d.docstate IN (2, 3) " +
                   "     AND d.createdat BETWEEN TO_DATE(" + date2sql_ora(Дата_движений_от.AddDays(-1)) + " , 'dd.mm.yyyy') AND TO_DATE(" + date2sql_ora(Дата_движений_до) + ", 'dd.mm.yyyy') " +
                   "     AND d.locationto = " + CachedQuerySingle(" select value from RABAEV.RRL_CONSTANTS where name='storeloc' ") + "  " +
                   "     AND s.article IN ( " + SQL_IN + " ) AND s.doctype = d.doctype " +
                   "    AND s.docid = d.ID " +
                   "    AND osnov.doctype = d.doctype " +
                   "    AND osnov.ID = d.ID " +
                   " GROUP BY s.article, baseid " ;

                }
                else
                {
                    strSQL = " SELECT s.article Артикул, " +
                      "  SUM(s.quantity) Колво, d.ID " +
                      "  FROM supermag.smdocuments   d, " +
                      "  supermag.smspec   s " +
                      "  WHERE d.doctype IN ('WI', 'IW') " +
                      "     AND d.docstate IN (2, 3) " +
                      "     AND d.createdat BETWEEN TO_DATE(" + date2sql_ora(Дата_движений_от.AddDays(-1)) + " , 'dd.mm.yyyy') AND TO_DATE(" + date2sql_ora(Дата_движений_до) + ", 'dd.mm.yyyy') " +
                      "     AND d.locationto = " + CachedQuerySingle(" select value from RABAEV.RRL_CONSTANTS where name='storeloc' ") + "  " +
                      "     AND s.article IN ( " + SQL_IN + " ) AND s.doctype = d.doctype " +
                      "    AND s.docid = d.ID " +
                      " GROUP BY s.article, d.ID ";
                }


            ora_com.CommandText = strSQL;

            try
            {

                ora_conn = new OracleConnection();
                ora_conn.ConnectionString = SM_CONNECTION_STRING();
                ora_conn.Open();
                ora_com.Connection = ora_conn;
                ora_reader = ora_com.ExecuteReader();

                while ( ora_reader.Read() )
                {
                    object[] values1 = new object[5];
                    for (int yy = 0; yy < 3; yy++)
                    {
                        values1[yy] = ora_reader.GetValue(yy).ToString();
                    }
                    key = values1[0].ToString().Trim().ToUpper() + "_" + values1[1].ToString().Trim();
                    lines_SM[key] = new object[] { values1[0], values1[1], values1[2] };
                    pos1++;
                }

                ora_reader.Close();
                ora_conn.Close();
               // MessageBox.Show("Сколичество движений по СМ = " + pos1.ToString());
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message + " " + key);
            }



           

            foreach (string kk in lines_SM.Keys)
            { // ЦИКЛ ===============================================
                object[] arr_2_res = new object[7];
                object[] vvv;
                if (lines_WMS.TryGetValue(kk, out vvv))
                {
                    arr_2_res[0] = vvv[0];// номер накладной
                    arr_2_res[1] = vvv[1];// артикул
                    arr_2_res[2] = vvv[2];// количество в ВМС
                    arr_2_res[3] = lines_SM[kk][2]; // количество в СМ 
                    lines_RESULT.Add(kk, arr_2_res);
                    lines_WMS.Remove(kk);
                }
                else
                {
                    arr_2_res[0] = lines_SM[kk][0];// номер накладной
                    arr_2_res[1] = lines_SM[kk][1];// артикул
                    arr_2_res[2] = 0;// количество в ВМС
                    arr_2_res[3] = lines_SM[kk][2]; // количество в СМ 
                    arr_2_res[5] = "нет в WMS";
                    string keyrr = "";
                    keyrr = lines_SM[kk][0].ToString().Trim().ToUpper() + "_" + lines_SM[kk][1].ToString().Trim();
                    lines_RESULT.Add( keyrr, arr_2_res );
                }
            } // ЦИКЛ ===============================================


            foreach (string kkk in lines_WMS.Keys)
            {
                object[] arr_2_res = new object[7];
                arr_2_res[0] = lines_WMS[kkk][0];// номер накладной
                arr_2_res[1] = lines_WMS[kkk][1];// артикул
                arr_2_res[2] = lines_WMS[kkk][2];// количество в ВМС
                arr_2_res[3] = 0; // количество в СМ
                arr_2_res[4] = 0; // lines_WMS[kkk][3];// количество
                arr_2_res[5] = "нет в СМ";
                string keyuuu = "";
                keyuuu = lines_WMS[kkk][0].ToString().Trim().ToUpper() + "_" + lines_WMS[kkk][1].ToString().Trim();
                lines_RESULT.Add( keyuuu, arr_2_res );
            }


            // =======================================================================
            //  Dictionary<string, object[]> lines_RESULT 
            string strSQL7 = " select acticul, name , cl.ware_id , art.cell from rrl_articuls art , rrl_cells cl where acticul in (" + SQL_IN + ") and art.cell=cl.cell ";
            Dictionary<object, Dictionary<object, object>> names = get_wms_sql_result_dictionary2(strSQL7);

          
            List<Dictionary<string, object>> return1 = new List<Dictionary<string, object>>();
            foreach( string k1 in lines_RESULT.Keys )
            {
                Dictionary<string, object> row1 = new Dictionary<string, object>();
                row1["key"]=lines_RESULT[k1].GetValue(0);
                row1["articul"] = lines_RESULT[k1].GetValue(1);
                row1["КолвоWMS"] = lines_RESULT[k1].GetValue(2);
                row1["КолвоСМ"] = lines_RESULT[k1].GetValue(3);
                row1["Разница"] = obj2double(lines_RESULT[k1].GetValue(3)) - obj2double(lines_RESULT[k1].GetValue(2));
                if (names.ContainsKey(lines_RESULT[k1].GetValue(1)))
                {
                    row1["Имя товара"] = names[lines_RESULT[k1].GetValue(1)]["NAME"];
                    row1["Склад"] = names[lines_RESULT[k1].GetValue(1)]["WARE_ID"];
                    row1["ЯчейкаОтбора"] = names[lines_RESULT[k1].GetValue(1)]["CELL"];
                }
                if (obj2double(row1["Разница"]) != 0)
                {
                    return1.Add(row1);
                }
            }

            return return1;
        }



        private void сверитьВеделенныеЗаНеделюToolStripMenuItem_Click(object sender, EventArgs e)
        {
            DateTime Дата_движений_от = DateTime.Today.AddDays(-7);
            DateTime Дата_движений_до = DateTime.Today.AddDays(-1);
            СравнитьПриходыПоАртикуламЗаПериод(Дата_движений_от, Дата_движений_до );
        }

        public void СравнитьПриходыПоАртикуламЗаПериод(DateTime Дата_движений_от ,DateTime Дата_движений_до ) {

            bool Сравнивать_по_ЗаказамОснованиям=true;
            List<Dictionary<string, object>> result1 = new List<Dictionary<string, object>>();
            List<string> arts = new List<string>();
            int i=0;
            foreach( DataGridViewRow dr in    dataGridView11.Rows )
            {
                if ( obj2bool( dr.Cells[5].Value ) == true)
                {
                    i++;
                    string art = dr.Cells[0].Value.ToString();
                    arts.Add(art);
                }

                if (i > 500)
                {
                    List<Dictionary<string, object>> ret1 = Сравнить_приходные_накладные(arts, Сравнивать_по_ЗаказамОснованиям, Дата_движений_от, Дата_движений_до);
                    arts.Clear();

                    foreach(Dictionary<string, object> rw1 in ret1)  result1.Add(rw1);

                }
            }


            List<Dictionary<string, object>> ret2 = Сравнить_приходные_накладные(arts, Сравнивать_по_ЗаказамОснованиям, Дата_движений_от, Дата_движений_до);
            foreach (Dictionary<string, object> rw1 in ret2) result1.Add(rw1);

            ShowArray(result1, "Сравнение приходов");
        }

