          "  " +//TRANSPORT_TASK.tt_wares(tt.id) СКЛАДЫ , rrl_tt_voditel_info( tt.voditel_id ) Водитель ,
          " TRANSPORT_TASK.TT_VODITEL_TEL( tt.voditel_id ) Телефон ,  tt.TRANSPORT  " +
          " from rrl_sborka_pallets pts , rrl_transport_task tt where  " +
          " tt.id = pts.transtask_id(+)  and tt.condition<>'ВЫПУЩЕН'  " +
          " and pts.create_date > systimestamp -2 and pts.ware_id in ( " + ware_id + " ) " +
          " group by  tt.id , RRL_TT_READY_PERC( tt.id  ) ,  tt.condition , tt.voditel_id ,  tt.TRANSPORT " +
          " order by max( pts.checking_time ) desc ";


            ЗАПРОСЫ ftr = new ЗАПРОСЫ();
