        private void скомплектованныеРейсыНеОтмеченныеНаОхранеToolStripMenuItem_Click(object sender, EventArgs e)
        {



            string strSQL = " SELECT   tt.ID, MAX (pts.checking_time) Время_сборки, " +
            " rrl_tt_regions (tt.ID) РЕГИОНЫ, " +
            " transport_task.tt_voditel_tel (tt.voditel_id) Телефон, tt.transport " +
            "    FROM rrl_sborka_pallets pts, rrl_transport_task tt " +
            "   WHERE transport_task.tt_unready_count (tt.ID) = 0 " +
            "      AND tt.ID = pts.transtask_id(+) " +
            "     AND tt.condition <> 'ВЫПУЩЕН' " +
            "    AND pts.create_date > SYSTIMESTAMP - 8 " +
            "    AND pts.create_date < SYSTIMESTAMP - 2 " +
            "    AND pts.ware_id IN (3) " +
            " GROUP BY tt.ID, " +
            "         rrl_tt_ready_perc (tt.ID), " +
            "         tt.condition, " +
            "         tt.voditel_id, " +
            "         tt.transport " +
            " ORDER BY MAX (pts.checking_time) DESC ";

         ShowQuery(strSQL, "Скомплектованные рейсы, не отмеченные на охране более недели.");

        }

