            DateTime dt2 = dt1.AddDays(1);
            if (checkBox4.Checked)
            {
                dt2 = БИЛЛИНГ_ДО.Value;
            }


            
            string strSQL = "";

            strSQL = " select  Коробки  , строки , fp ,Вес , sborshik  СБОРЩИК , ware_id  , Дата , " +
            " billing.billing_sum( строки ,  Коробки  , Вес  , fp , ware_id  ) сделка    " +
            " from (  " +
            " select  sum( rs.pack_count ) Коробки  , count( rs.id ) строки ,  " +
            " sum( obj2number(  rs.is_full_pallet ) ) fp , sum( rs.original_order_weight ) Вес ,  " +
            " pts.sborshik , pts.ware_id ,  To_date(   To_char( pts.checking_time , 'dd.mm.YYYY' ) , 'dd.mm.YYYY' ) Дата  " +
            " from rrl_sborka_pallets pts , rrl_sborka_pallet_rows rs  where  pts.ware_id in (" + ware_id + ") and " +
            " pts.pallet_uid=rs.pallet_uid and " +
            " pts.checking_time >=   " + datetime2sql_ora(dt1, dt1_min) + " and " +
            " pts.checking_time <=   " + datetime2sql_ora(dt2, dt2_min) + " " +
            " group by pts.sborshik , pts.ware_id ,  " +
            "  To_date(   To_char( pts.checking_time , 'dd.mm.YYYY' ) , 'dd.mm.YYYY' ) " +
            " ) ";

            string strSQL2 = " select  Коробки  , строки , fp ,Вес , sborshik СБОРЩИК  , ware_id  , Дата , " +
            " billing.billing_sum( строки ,  Коробки  , Вес  , fp , ware_id  ) сделка , pallet_uid  " + 
            " from (  " + 
            " select pts.pallet_uid , sum( rs.pack_count ) Коробки  , count( rs.id ) строки ,  " + 
            " sum( obj2number(  rs.is_full_pallet ) ) fp , sum( rs.original_order_weight ) Вес ,  " + 
            " pts.sborshik , pts.ware_id ,  To_date(   To_char( pts.checking_time , 'dd.mm.YYYY' ) , 'dd.mm.YYYY' ) Дата  " +
            " from rrl_sborka_pallets pts , rrl_sborka_pallet_rows rs  where   pts.ware_id in (" + ware_id + ") and  " + 
            " pts.pallet_uid=rs.pallet_uid and " +
            " pts.checking_time >=   " + datetime2sql_ora(dt1, dt1_min) + " and " +
            " pts.checking_time <=   " + datetime2sql_ora(dt2, dt2_min) + " " +
            " and pts.sborshik='[СБОРЩИК]' " + 
            " group by pts.sborshik , pts.ware_id ,  " + 
            "  To_date(   To_char( pts.checking_time , 'dd.mm.YYYY' ) , 'dd.mm.YYYY' ) " + 
            "  , pts.pallet_uid " + 
            " ) ";


