        private void приходыЗаПериодToolStripMenuItem_Click(object sender, EventArgs e)
        {
            DateTime dt1_min = БИЛЛИНГ_ОТ_время.Value;
            DateTime dt2_min = БИЛЛИНГ_ДО_время.Value;
            string ware_id = this.wms_user.ware_id.ToString();

            if (m_выбранный_склад.Text != "")
            {
                try { ware_id = m_выбранный_склад.Text; }
                catch { }
            }

            if (ware_id == "") { ware_id = "" + this.wms_user.ware_id.ToString() + ""; }

            DateTime dt1 = БИЛЛИНГ_ОТ.Value;
            DateTime dt2 = dt1.AddDays(1);
            if (checkBox4.Checked)
            {
                dt2 = БИЛЛИНГ_ДО.Value;
            }

   
            string strSQL = "select nkl.id ПОСТАВКА , pts.articul , art.name , nkl.date_of_accept ,  " + 
            "   sum( pts.unit_count*pts.price ) стоимость ,  " + 
            "   round( sum( pts.unit_count*pts.price )/sum( pts.unit_count ) , 2) цена ,  " +
            "   round(  sum(  pts.unit_count ) , 2 ) колво_нетто, count(pts.uid_pallet) колво_палл ,  " +
            "   sum( pts.weight_brutto - pts.weight_tn )  ВесБрутто ,  " +
            "    round(  sum( pts.defect_perc_income*pts.unit_count ) / sum( pts.unit_count ) , 2) процент_брака_прием , " +
            "    round( sum( pts.defect_perc *pts.unit_count ) / sum( pts.unit_count ) , 2 ) процент_брака , max( pts.unit_count ) ВЛОЖЕННОСТЬ , " + 
            "  round( AVG ( (  pts.weight_brutto- pts.weight_tn ) / pts.count_kor  )  , 2 ) вес_брутто_кор , " +
            "  round( AVG ( (  pts.unit_count) / pts.count_kor ) ) вложенность_в_кор , " + 
            "  round(  avg(1800/pts.count_kor) , 2 ) высотаКор   " + 
            "    from rrl_pallets pts , rrl_prihod_naklad nkl , rrl_articuls art " + 
            "    where nkl.id=pts.prihod_naklad_id " + 
            "    and nkl.ware_id = (" + ware_id + ") " + 
            "    and nkl.date_of_accept >= " + datetime2sql_ora(dt1, dt1_min) + " " + 
            "    and nkl.date_of_accept <= " + datetime2sql_ora(dt2, dt2_min) + " " + 
            "    and pts.articul=art.acticul " +
            "    and pts.count_kor>0 " +
            "    group by nkl.id , pts.articul , nkl.date_of_accept ,  art.name " + 
            "    having  sum( pts.unit_count )>0";

            string strSQL2 = "select pts.uid_pallet  , nkl.id , pts.articul , art.name , nkl.date_of_accept ,  " +
            "   ( pts.unit_count*pts.price ) стоимость ,  " +
            "    ( pts.unit_count*pts.price )/( pts.unit_count ) цена ,  " +
            "    (  pts.unit_count ) колво_нетто ,   " +
            "    ( pts.weight_brutto - pts.weight_tn )  ВесБрутто ,  " +
            "    ( pts.defect_perc_income*pts.unit_count ) / ( pts.unit_count ) процент_брака_прием , " +
            "    ( pts.defect_perc *pts.unit_count ) / ( pts.unit_count ) процент_брака " +
            "    from rrl_pallets pts , rrl_prihod_naklad nkl , rrl_articuls art " +
            "    where nkl.id=pts.prihod_naklad_id and nkl.id =[ПОСТАВКА] " +
            "    and nkl.ware_id = (" + ware_id + ") " +
            "    and nkl.date_of_accept >= " + datetime2sql_ora(dt1, dt1_min) + " " +
            "    and nkl.date_of_accept <= " + datetime2sql_ora(dt2, dt2_min) + " " +
            "    and pts.articul=art.acticul and ( pts.unit_count>0 ) ";

            List<string> SubQueries = new List<string>();
            SubQueries.Add(strSQL2);
            object[] o = ShowQuery(strSQL, "Приходы товара за период", new Point(1, 1), "", SubQueries);



        }

        private void сторнироватьПаллетToolStripMenuItem_Click(object sender, EventArgs e)
        {

            #region  СТОРНИРОВАНИЕ
            if (!has_right("OP_STORNO"))
            {
                MessageBox.Show("Нет прав на OP_STORNO");
                return;
            }
            string CURRENT_PAL = dataGridView22.CurrentRow.Cells[1].Value.ToString();

            Dictionary<string, object> values = new Dictionary<string, object>();
            values["pall_uid1"] = CURRENT_PAL;
            values["user_id1"] = wms_user.user_id;
            int ret = obj2int32( wms_get_spfunction_value2("REMAINS.storno_op", values, OracleType.Int32, 0));
            if (ret == -3)
            {
                MessageBox.Show("Маршрут данного паллета был отгружен (закрыт)");
                return;
            }

            if (ret == -2)
            {
                MessageBox.Show("Запись не найдена");
                return;
            }

            dataGridView21_CellEnter(null, null);
            MessageBox.Show("Сторно проведено.");
            #endregion

        }

