            {
                try { ware_id = m_выбранный_склад.Text; }
                catch { }
            }

            if (ware_id == "") { ware_id = "" + this.wms_user.ware_id.ToString() + ""; }

            DateTime dt1 = БИЛЛИНГ_ОТ.Value;
            DateTime dt2 = dt1.AddDays(1);
            if (checkBox4.Checked)
            {
                dt2 = БИЛЛИНГ_ДО.Value;
            }



            string strSQL = "select www.name СКЛАД , to_char( pts.create_date , 'dd.mm.YYYY' ) ДАТА , " +
                            "    count( distinct pts.pallet_uid ) КОЛВОПАЛЛ ,  " +
                            "    round(sum( rs.order_weight )) ВЕС , " +
                            " round( sum( rs.taresize*rs.pack_count )/1000000 ) ОБЪЕМ , " +
                            "    round( sum( rs.quantity*art.last_price )/count( distinct pts.pallet_uid ) )СР_СТОИМ_ПАЛЛЕТ " + 
                            "    from rrl_sborka_pallet_rows rs , rrl_sborka_pallets pts , rrl_articuls art , rrl_wares www " + 
                            "    where pts.pallet_uid = rs.pallet_uid  " + 
                            "    and art.acticul=rs.articul " +
                            "    and pts.create_date >= " + datetime2sql_ora(dt1, dt1_min) + " " +
                            "    and pts.create_date <= " + datetime2sql_ora(dt2, dt2_min) + " " + 
                            "    and www.id = pts.ware_id   " + 
                            "    group by  to_char( pts.create_date , 'dd.mm.YYYY' ) , www.name " + 
                            "    order by to_char( pts.create_date , 'dd.mm.YYYY' )  , www.name ";





            string strSQL2 = "select  " +
                            "    count( distinct pts.pallet_uid ) КОЛВОПАЛЛ ,  " +
                            "    round(sum( rs.order_weight )) ВЕС , " +
                            "    round( sum( rs.taresize*rs.pack_count )/1000000 ) ОБЪЕМ , " +
                            "    round( sum( rs.quantity*art.last_price )/count( distinct pts.pallet_uid ) ) СР_СТОИМ_ПАЛЛЕТ " +
                            "    from rrl_sborka_pallet_rows rs , rrl_sborka_pallets pts , rrl_articuls art , rrl_wares www " +
                            "    where pts.pallet_uid = rs.pallet_uid  " +
                            "    and art.acticul=rs.articul " +
                            "    and pts.create_date >= " + datetime2sql_ora(dt1, dt1_min) + " " +
                            "    and pts.create_date <= " + datetime2sql_ora(dt2, dt2_min) + " " +
                            "    and www.id = pts.ware_id  and www.NAME='[СКЛАД]' and  to_char( pts.create_date , 'dd.mm.YYYY' )= '[ДАТА]' " +
                            "    group by  rs.articul    ";
                         

            List<string> SubQueries = new List<string>();
            SubQueries.Add(strSQL2);
            object[] o = ShowQuery(strSQL, "Стоимость отгруженных паллет", new Point(1, 1), "", SubQueries);

        }

