        private void сравнениеПаллетИЗаказоввТомЧислеВычеркиToolStripMenuItem_Click(object sender, EventArgs e)
        {

            Dictionary<string, string> sts = new Dictionary<string, string>();
            string str1 = "";
            int yy = 0;
            foreach (DataGridViewRow dr in dataGridView2.Rows)
            {
                if (Convert.ToBoolean(dr.Cells[0].Value))
                {
                    yy++;
                    string st = dr.Cells[1].Value.ToString();
                    if (!sts.ContainsKey(st))
                    {
                        sts[st] = st;
                        str1 = str1 + " '" + st + "' ,";
                    }
                }
            }

            str1 = str1.Trim(',');

            // ------------------------------------------------------------------------

            string strSQL = " select shortname,  articul , sum(ЗАКАЗАНО) ЗАКАЗАНО ,sum(Собрано) Собрано " + 
            " from ( select rs.shortname , rs.articul , sum(rs.original_quantity) ЗАКАЗАНО , 0 Собрано " + 
            " from rrl_orders rd, rrl_order_rows rs where rd.ID=rs.ORDER_ID  " +
            " and rd.ORD_NUMBER in ( " + str1 + "  )   " + 
            "      GROUP BY rs.shortname, rs.articul " + 
            " union " + 
            "SELECT   rs.shortname, rs.articul, 0 ЗАКАЗАНО, SUM (rs.quantity) Собрано " + 
            "    FROM rabaev.rrl_sborka_pallets pp, rrl_sborka_pallet_rows rs " + 
            "   WHERE rs.pallet_uid = pp.pallet_uid " +
            "     and pp.ORIGINAL_ST_NUMBER in ( " + str1 + " ) " + 
            " GROUP BY rs.shortname, rs.articul " + 
            ") GROUP BY shortname ,  articul ";

            List<string> subq = new List<string>();
            subq.Add(
                 " select shortname,  articul , sum(ЗАКАЗАНО) ЗАКАЗАНО ,sum(Собрано) Собрано , ORD_NUMBER " +
            " from ( select rs.shortname , rs.articul , sum(rs.original_quantity) ЗАКАЗАНО , 0 Собрано , ORD_NUMBER " + 
            " from rrl_orders rd, rrl_order_rows rs where rd.ID=rs.ORDER_ID  " +
            " and rd.ORD_NUMBER in ( " + str1 + "  ) and articul='[ARTICUL]'  " +
            "      GROUP BY rs.shortname, rs.articul , ORD_NUMBER " + 
            " union " +
            "SELECT   rs.shortname, rs.articul, 0 ЗАКАЗАНО, SUM (rs.quantity) Собрано , ORIGINAL_ST_NUMBER ORD_NUMBER  " + 
            "    FROM rabaev.rrl_sborka_pallets pp, rrl_sborka_pallet_rows rs " +
            "   WHERE rs.pallet_uid = pp.pallet_uid and rs.articul='[ARTICUL]' " +
            "     and pp.ORIGINAL_ST_NUMBER in ( " + str1 + " ) " +
            " GROUP BY rs.shortname, rs.articul , ORIGINAL_ST_NUMBER " +
            ") GROUP BY shortname ,  articul , ORD_NUMBER ");
            Point p = new Point(0,0);
            ShowQuery(strSQL, "Отчет по сборке по выделенным ст " ,p ,"",subq );





        }

        private void большаяРазницаМеждуЗаказомИПаллетамиToolStripMenuItem_Click(object sender, EventArgs e)
        {


            Dictionary<string, string> sts = new Dictionary<string, string>();
            string str1 = "";
            int yy = 0;
            foreach (DataGridViewRow dr in dataGridView2.Rows)
            {
                if (Convert.ToBoolean(dr.Cells[0].Value))
                {
                    yy++;
                    string st = dr.Cells[1].Value.ToString();
                    if (!sts.ContainsKey(st))
                    {
                        sts[st] = st;
                        str1 = str1 + " '" + st + "' ,";
                    }
                }
            }
            str1 = str1.Trim(',');
            string strSQL = "";

             strSQL = "  select     SHORTNAME , ARTICUL , ST_NUMBER , sum( ЗАКАЗАНО ) , sum ( Собрано ) " + 
            " from  " + 
            " ( select  RS.SHORTNAME , RS.ARTICUL , ST_NUMBER , 0 ЗАКАЗАНО  , sum(RS.QUANTITY) Собрано   " + 
            " from  RABAEV.RRL_SBORKA_PALLETS PP   , RRL_SBORKA_PALLET_ROWS RS where  RS.PALLET_UID  = PP.PALLET_UID  " +
            " and  ( ST_NUMBER in ( " + strSQL + " ) or pp.original_st_number in  ( " + strSQL + "  ) ) " + 
            "  group by RS.SHORTNAME , RS.ARTICUL , ST_NUMBER " + 
            " union select   " + 
            " rs2.shortname  ,  rs2.articul , ord_number ST_NUMBER , sum( rs2.original_quantity ) ЗАКАЗАНО , 0 Собрано  " + 
            "  from rrl_orders rd , rrl_order_rows rs2 where rd.id=rs2.order_id " +
            "  and rd.ord_number in ( " + strSQL + "  ) " + 
            "  group by SHORTNAME , ARTICUL , ord_number " + 
            " )      group by SHORTNAME , ARTICUL , ST_NUMBER  " +
            " having (  abs( sum( ЗАКАЗАНО ) - sum ( Собрано ) )/( sum( ЗАКАЗАНО ))>0.5 and  abs( sum( ЗАКАЗАНО ) - sum ( Собрано ) )>100 ) ";
            
