        private void подтвердитьКонтрольЦенToolStripMenuItem_Click(object sender, EventArgs e)
        {
            // Подтверждает ценовой контроль.
            // Ценовой контроль возможен только для заявок во 2-м статусе
            if (dataGridView_prihod.CurrentRow == null)
                return;
            long id = obj2int(dataGridView_prihod.CurrentRow.Cells[6].Value);

            СверкаЦен form_compare = new СверкаЦен();
            form_compare._parent = this;
            form_compare.id =  id ;
            form_compare.ShowDialog();
            if (form_compare.m_СверкаНеПройдена)
            {
                return;
            }
            // PRIHOD.close_price_control( prih_id int ) return int

            Dictionary<string, object> values = new Dictionary<string, object>();
            values["prih_id"] = id;
            object ret = wms_get_spfunction_value2("PRIHOD.close_price_control", values, OracleType.Int32, 0);

            int ret2 = obj2int32(ret);

            //   2- уже пройдена сверка цен ; 3-накладная закрыта ; 1 - ок ; нет ид=-1
             switch (ret2)
             {

                             case -4: // 
                                MessageBox.Show("Укажите госномер авто");    
                                 break;
                             case -1: // 
                                 MessageBox.Show("Нет прихода с таким идентификатором.");
                                 break;

                            case 1: // 
                                MessageBox.Show( "Сверка цен пройдена. Машина поставлена в очередь." );            
                                break;

                            case 2: // 
                                MessageBox.Show("Сверка цен была пройдена раннее.");       
                                break;

                            case 3: // 
                                MessageBox.Show("Накладная закрыта.");       
                                break;

                            default:
                                break;
              }



             //MessageBox.Show("Сверка цен пройдена");       
             dataGridView_prihod_CellEnter( null , null );


        }

