        private void PRIHOD_PRIORITY_TextChanged(object sender, EventArgs e)
        {
            // У прихода поменяли док
            if (dataGridView_prihod.CurrentRow == null)
            {
                return;
            }

            long id = obj2int(dataGridView_prihod.CurrentRow.Cells[6].Value);
            string priority_text = PRIHOD_PRIORITY.Text.Trim();
            int priority_id = 0;
            if (priority_text == "")
            {
                return;
            }


            switch (priority_text)
            {
                case "В ОЧЕРЕДИ":
                    priority_id =10 ;
                    break;
                case "НЕ СПЛАНИРОВАН" :
                    priority_id = 30;
                    break;
                case "ОТКЛОНЕН"  :
                    priority_id = 20;
                    break;
                case "ПРИОРИТЕТ"  :
                    priority_id = 5;
                    break;
                default:
                    priority_id = 10;
                    break;
            }


                       if (!has_right("CHANGE_PRIHOD_PRIORYTY"))
                        {
                            MessageBox.Show("У вас нет прав на изменение приоритета приемки");
                            return;
                        } 

             // function ( prih_id int ,  new_priority_id int , new_user_id varchar2 )
            Dictionary<string, object> values = new Dictionary<string, object>();
            values["prih_id"] = id;
            values["new_priority_id"] = priority_id;
