            object ret = wms_get_spfunction_value2("PRIHOD.set_priority", values, OracleType.Int32, 0);
            if (obj2int32(ret) != 1)
            {
                MessageBox.Show("Док не установлен. Возможно накладная закрыта.");
                return;
            }
        }

