        private void отчетПоПриемкеПриходовЗаПериодToolStripMenuItem_Click(object sender, EventArgs e)
        {


            DateTime dt1 = БИЛЛИНГ_ОТ.Value;
            DateTime dt2 = dt1;
            if (checkBox4.Checked)
            {
                dt2 = БИЛЛИНГ_ДО.Value.AddDays(1);
            }


            //



            string fields = "";
            string wheres = "";
            string sub_filter = "";



            string strSQL = " SELECT t.ID НОМЕР , shipment_date ДАТА ,  t.PAY_REGION РЕГИОН , " +
            "   RRL_TT_ADDR_COUNT(t.ID) КОЛВО_ТОЧЕК , RRL_TT_VODITEL_INFO(VODITEL_ID) ФИО_ВОДИТЕЛЯ  , " +
            "   PRICE СУММА_ЗА_РЕЙС  , t.ADDR_PREMIO ИЗ_НИХ_ПРЕМИЯ , tr. DOVERENNOST_OT " +
            "   FROM rrl_transport_task t , rrl_tr_voditel tr " +
            "   WHERE   t.VODITEL_ID=tr.ID and  shipment_date >= " + date2sql_ora(dt1) +
            "   and shipment_date <= " + date2sql_ora(dt2) + " AND t.deleted <> 1 and tr. DOVERENNOST_OT='МОНЕТКА' ";


            //===============================================================

            string ware_id = wms_user.ware_id.ToString();
            string strSQL2 = "";
            if (m_выбранный_склад.Text != "")
            { 
                ware_id = m_выбранный_склад.Text;
                strSQL2 = " and ware_id in (" + ware_id + ")  "; 
            }
            else {
                ware_id = "";
                strSQL2 = "";
            }

            

             strSQL = "  select rownum ПП , id УИД , ПОСТАВЩИК , ДОК , МАШИНА , " +
                " ТЕЛ_ВОДИТЕЛЯ , ВРЕМЯ_ЦК  , СКЛАД ,  ПРИОРИТЕТ,  ПРИНЯТЬ_ДО , ВРЕМЯ_ПРИЕМКИ , Время_вызова_на_док ,  " +
                " VODITEL_NAME ИМЯ_ВОДИТЕЛЯ , USER_ID ИМЯ_ПРИЕМЩИКА , КОЛВО_ПАЛЛ , zakaz_number НОМЕР_ЗАКАЗА " +
                " from ( select  invite_time Время_вызова_на_док , zakaz_number , nkl.id ,  nkl.postavshik_name ПОСТАВЩИК , nkl.dock ДОК ,  " +
                            "  nkl.vechile_number МАШИНА , nkl.voditel_phone_numb ТЕЛ_ВОДИТЕЛЯ ,  " +
                            "  nkl.planning_accept_time ПРИНЯТЬ_ДО  , nkl.CHECKING_TIME ВРЕМЯ_ЦК , "+
                            "  TIME_OF_2_STATUS ВРЕМЯ_ПРИЕМКИ , VODITEL_NAME , USER_ID , " +
                            "  rrl_skladname_by_id( nkl.ware_id ) СКЛАД , nkl.priority1 ПРИОРИТЕТ , "+
                            "  PRIHOD.prihod_pall_count( nkl.id ) КОЛВО_ПАЛЛ " +
                            "  from rrl_prihod_naklad nkl  " +
