                          "    sum( rs.quantity ) КОЛВО  ,  " +
                          "    round(sum( rs.order_weight )) ВЕС , " +
                          "    round( sum( rs.taresize*rs.pack_count )/1000000 ) ОБЪЕМ , " +
                          "    round( sum( rs.quantity*art.last_price ) , 2 ) СТОИМОСТЬ " +
                          "    from rrl_sborka_pallet_rows rs , rrl_sborka_pallets pts , rrl_articuls art , rrl_wares www " +
                          "    where pts.pallet_uid = rs.pallet_uid  " +
