        private void вычеркиПоАртикуламЗаПериодToolStripMenuItem_Click(object sender, EventArgs e)
        {

            string arts = "";

            foreach (string art in  фильтр_артикулов.Lines  )
            {
                    arts = arts + " '" + art + "' ,";
            }
            arts = arts.Trim(',').Trim();

            if (arts == "") return;

            DateTime dt1 = DateTime.Today;
            DateTime dt2 = DateTime.Today.AddDays(30);
            
            string strSQL ;
            strSQL = " SELECT   pts.st_number, art.acticul, art.NAME, www.NAME СКЛАД, " +
                     " TO_CHAR (pts.create_date, 'dd.mm.YYYY') ДАТА, (rs.quantity) КОЛВО, " +
                     " original_quantity Плановое_колво, ROUND ( (rs.order_weight)) ВЕС, " +
                     " ROUND (  (rs.taresize * rs.pack_count) / 1000000) ОБЪЕМ, " +
               "       ROUND (  (rs.quantity * art.last_price), 2) СТОИМОСТЬ " +
               " FROM rrl_sborka_pallet_rows rs, " +
               "      rrl_sborka_pallets pts, " +
               "      rrl_articuls art, " +
               "      rrl_wares www " +
               "   WHERE pts.pallet_uid = rs.pallet_uid " +
               "   AND art.acticul = rs.articul " +
               "   AND pts.create_date >= " + datetime2sql_ora(БИЛЛИНГ_ОТ.Value, БИЛЛИНГ_ОТ_время.Value) + " " +
               "   AND pts.create_date <= " + datetime2sql_ora(БИЛЛИНГ_ДО.Value, БИЛЛИНГ_ДО_время.Value) + "  " +
               "   AND www.ID = pts.ware_id " +
               "   AND art.acticul IN ( " + arts + " ) " +
               "   AND ( abs( rs.quantity - original_quantity )/ original_quantity >0.99  ) " +
               "   and ( rs.quantity < original_quantity ) " +
               "   ORDER BY art.NAME, TO_CHAR (pts.create_date, 'dd.mm.YYYY'), www.NAME ";

            ShowQuery( strSQL , "Отгрузка со склада за период артикулов: " + arts);

        }

