        private void производительностьToolStripMenuItem1_Click(object sender, EventArgs e)
        {

            string ware_id = this.wms_user.ware_id.ToString();

            if (m_выбранный_склад.Text != "")
            {
                ware_id = obj2str(m_выбранный_склад.Text);
            }

            string strSQL = " SELECT  p.ware_id  , u1.Name ,  SUM ((rrl_pal_row_count (p.pallet_uid))) СТРОКИ, SUM (rrl_pal_kor_count (p.pallet_uid)) КОРОБКИ,   " +
                "   sum( TRIAL_WEIGHT- WOOD_WEIGHT )  ВЕС_По_Весовому_Контролю ,  " +
                "   sum( RABAEV.RRL_PAL_WEIGHT( PALLET_UID )) ВЕС_По_Логопараметрам ,     COUNT (DISTINCT p.sborshik) СБОРЩИКИ, " +
                "   TO_CHAR (p.checking_time, 'HH24-DD-MM-YYYY') Время,     TO_CHAR (p.checking_time, 'HH24') ЧАС, " +
                "   TO_CHAR (p.checking_time, 'DD') ДЕНЬ,     TO_CHAR (p.checking_time, 'MM') МЕС, TO_CHAR (p.checking_time, 'YYYY') ГОД,  " +
                "   ROUND ( sum( p.TRIAL_WEIGHT ) , 0) ВЕС   FROM rrl_sborka_pallets p, rusers u1  " +
                "   WHERE (NOT ( p.sborshik IS NULL))    AND (p.sborshik = u1.ID(+))  " +
                "   AND (p.checking_time >= " + datetime2sql_ora( БИЛЛИНГ_ОТ.Value , БИЛЛИНГ_ОТ_время.Value  ) + " )   " +
                "   AND (p.checking_time <=  " + datetime2sql_ora(БИЛЛИНГ_ДО.Value, БИЛЛИНГ_ДО_время.Value) + "  )  " +
                "   GROUP BY  u1.Name ,  TO_CHAR (p.checking_time, 'HH24'),  TO_CHAR (p.checking_time, 'DD'),  " +
                "   TO_CHAR (p.checking_time, 'MM'),  TO_CHAR (p.checking_time, 'YYYY'),  TO_CHAR (p.checking_time, 'HH24-DD-MM-YYYY')  " +
                "   ORDER BY TO_CHAR (p.checking_time, 'YYYY'),  TO_CHAR (p.checking_time, 'MM' ),     TO_CHAR (p.checking_time, 'DD'),  " +
                "   TO_CHAR (p.checking_time, 'HH24') ";




            strSQL = " SELECT   RRL_SKLADNAME_BY_ID(p.ware_id) СКЛАД  ,  SUM ((rrl_pal_row_count (p.pallet_uid))) СТРОКИ , " +
               " SUM (rrl_pal_kor_count (p.pallet_uid)) КОРОБКИ , " +
               "   sum( TRIAL_WEIGHT- WOOD_WEIGHT )  ВЕС_По_Весовому_Контролю ,  " +
               "   sum( RABAEV.RRL_PAL_WEIGHT( PALLET_UID )) ВЕС_По_Логопараметрам ,     COUNT (DISTINCT p.sborshik) СБОРЩИКИ , " +
               "   TO_CHAR (p.checking_time, 'DD-MM-YYYY') Время , " +
               "   TO_CHAR (p.checking_time, 'DD') ДЕНЬ,     TO_CHAR (p.checking_time, 'MM') МЕС, TO_CHAR (p.checking_time, 'YYYY') ГОД,  " +
               "   ROUND ( sum( p.TRIAL_WEIGHT ) , 0) ВЕС   FROM rrl_sborka_pallets p, rusers u1  " +
               "   WHERE (NOT ( p.sborshik IS NULL))    AND (p.sborshik = u1.ID(+))  " +
               "   AND (p.checking_time >= " + datetime2sql_ora(БИЛЛИНГ_ОТ.Value, БИЛЛИНГ_ОТ_время.Value) + " )   " +
               "   AND (p.checking_time <=  " + datetime2sql_ora(БИЛЛИНГ_ДО.Value, БИЛЛИНГ_ДО_время.Value) + "  )  " +
               "   GROUP BY  RRL_SKLADNAME_BY_ID( p.ware_id ) ,   TO_CHAR (p.checking_time, 'DD'),  " +
               "   TO_CHAR (p.checking_time, 'MM') , TO_CHAR (p.checking_time, 'YYYY') , TO_CHAR (p.checking_time, 'DD-MM-YYYY')  " +
               "   ORDER BY   RRL_SKLADNAME_BY_ID( p.ware_id ) , TO_CHAR (p.checking_time, 'YYYY') , "+
               "   TO_CHAR (p.checking_time, 'MM' ) , TO_CHAR (p.checking_time, 'DD')  " +
               "   ";





            ЗАПРОСЫ ftr = new ЗАПРОСЫ();
            ftr._parent = this;
            ftr.sSQL = strSQL;
            ftr.Header_Text = "ПРОИЗВОДИТЕЛЬНОСТЬ СБОРЩИКОВ ЗА ПЕРИОД В КОРОБКАХ";
            ftr.pivot_rowfields = "СКЛАД";
            ftr.pivot_columnfield = "ДЕНЬ";
            ftr.pivot_function = "SUM";
            ftr.pivot_functionfield = "КОРОБКИ";
            //ftr.repeat_time_in_seconds = 600;
            ftr.show_itogo_cols = true;
            ftr.show_itogo_rows = true;

            ftr.Show();

        }

