        private void загрузкаГруппыТоваровИзСМпоВсемАртикуламToolStripMenuItem_Click(object sender, EventArgs e)
        {
            OracleConnection ora_conn = new OracleConnection();
            ora_conn.ConnectionString = SM_CONNECTION_STRING();
            ora_conn.Open();

            foreach (DataGridViewRow dr in dataGridView11.Rows)
            {
                string art = dr.Cells[0].Value.ToString();
                //SyncCompileSQ(art, wms_user.ware_id, ora_conn);
                // ============================================================================= 
                OracleCommand ora_com = new OracleCommand();
                ora_com.Connection = ora_conn;


                ora_com.CommandText = " select tree, name from supermag.sacardclass cc where id in "+
                    " (select idclass from supermag.smcard where article = '" + art + "' ) ";
                    
                  
                    

                OracleDataReader ora_read = ora_com.ExecuteReader();
                if (ora_read.Read())
                {
                    string gr = obj2str(ora_read.GetValue(0));
                    string name = obj2str(ora_read.GetValue(1));
                    ExecuteOracleNonQuery("update rrl_articuls set GROUP_TOVARA= '" + gr + "' , GROUP_TNAME='" + name + "'  " +
                        " where acticul='" + art + "' ");

                } else { } 
                // =======================================================================

            }


            ora_conn.Close();
            MessageBox.Show( "Подгрузка завершена" );

        }

