                " rs.articul=art.acticul and  pts.addr = adr.addr and  " + 
                " rs.pallet_uid = pts.pallet_uid and pts.transtask_id in (  " + 
                " select   T.ID  from RRL_TRANSPORT_TASK  T   " + 
                " where  deleted<>1  and SHIPMENT_DATE >= " + date2sql_ora(БИЛЛИНГ_ОТ.Value)  +" " + 
                "    and SHIPMENT_DATE <=   " + date2sql_ora(БИЛЛИНГ_ДО.Value) + "    )  " + 
                " and not ( rs.transport_price is null )  " + 
                " group by  " + 
                " art.group_tovara , art.group_tname   , adr.region  " ;
            
            ShowQuery(strSQL, "Стоимость доставки артикулов за период: Транспортные затраты в разрезе групп.");
        }

