        public void ОтправитьПисьмаВМагазиныПоУехавшейМашине(long id)
        {
            // Проверяем - был - ли данный маршрут выпущен и не отправлен  EMAIL
            Dictionary<string, object> values = new Dictionary<string, object>();
            values["tt_id"] = id;
            object ret = wms_get_spfunction_value2("TRANSPORT_PLN.is_tt_just_out_go", values, OracleType.Int32, 0);
            //  is_tt_just_out_go( tt_id int )  return int 
            if (obj2int32(ret) == 1)
            { // Планируем и отправляем письмо



                // TRANSPORT_PLN upd_tt_perdiction( tt_id int , date_of_start timestamp ) 
                // планируем
                values = new Dictionary<string, object>();
                values["tt_id"] = id;
                values["date_of_start"] = DateTime.Now;
                ret = wms_get_spfunction_value2("TRANSPORT_PLN.upd_tt_perdiction", values, OracleType.Int32, 0);

                // Отправляем EMAIL
                #region ОТПРАВКА ПОЧТЫ
                string mail_body = "";
                string mail_head = "";

                #region  ФОРМИРОВАНИЕ ТЕЛА ПИСЬМА

                string str_s1 = " select TRANSPORT , RRL_TT_VODITEL_INFO( VODITEl_ID ) VOD , VODITEl_ID , TO_CHAR( TIME_OF_DAPARTURE ,'YYYY-MM-DD HH24:MI') TM " +
                            " from rrl_transport_task tt where tt.ID=" + id.ToString() + " ";
                List<Dictionary<object, object>> res0 = get_wms_sql_result_dictionary3(str_s1);


                foreach (Dictionary<object, object> ii in res0)
                {


                    string tel = "";
                    if (obj2int(ii["VODITEL_ID"]) > 0)
                    {
                        tel = obj2str(get_wms_sql_result_single(" select tel from rrl_tr_voditel where id=" + obj2int(ii["VODITEL_ID"]).ToString() + " "));
                        if (tel != "")
                        { tel = "<br>Телефон водителя:" + tel; }
                    }

                    mail_body = "<body>В Ваш магазин с РЦ выехала машина " + ii["TRANSPORT"] + ". Водитель " + ii["VOD"] + " " +
                        "Время выезда: " + ii["TM"] + "</br>" +
                        ".</br>Ожидаемый график движения машины: </br>";
                    mail_head = "В Ваш магазин с РЦ выехала машина " + ii["TRANSPORT"] + "";
                }

                string strSQL = "   select pts.addr ADDR , max(pts.ord) ORD , count(pts.pallet_uid) KPAL , " +
                                " max( plan_time_in_addr ) TIME_IN_ADDR , max( plan_time_out_addr ) TIME_OUT_ADDR , " +
                                " RRL_SKLADNAME_BY_ID(pts.ware_id) WRH , ad1.email EMAIL " +
                                " from rrl_sborka_pallets pts ,  rrl_addr  ad1 " +
                                " where pts.transtask_id=" + id.ToString() + "  and pts.addr = ad1.addr " +
                                " group by pts.addr ,  RRL_SKLADNAME_BY_ID(pts.ware_id) , ad1.email  " +
                                " order by max(pts.ord)  ";
                // Получили Список адресов с е-майлами с 
                List<Dictionary<object, object>> res1 = get_wms_sql_result_dictionary3(strSQL);
                Dictionary<string, string> emails = new Dictionary<string, string>();
                mail_body = mail_body + "<table><tr><th>Адрес</th><th>Колво паллет</th><th>Плановое время</th><th>принять до</th><th>Склад</th></tr>";
                foreach (Dictionary<object, object> i in res1)
                {
                    mail_body = mail_body + "<tr><td>" + i["ADDR"] + "</td><td>" + i["KPAL"] +
                        "</td><td>" + i["TIME_IN_ADDR"] + "</td><td>" + i["TIME_OUT_ADDR"] + "</td><td>" + i["WRH"] + "</td></tr>";
                    emails[i["ADDR"].ToString()] = i["EMAIL"].ToString();
                }
                mail_body = mail_body + "</table></body>";
                #endregion

                //Формирование письма
                foreach (string mag in emails.Keys)
                {
                    string eee = emails[mag];
                    if (eee.IndexOf("@") >= 0)
                    {
                        SmtpClient Smtp = new SmtpClient("192.168.0.1", 25);
                        MailMessage Message = new MailMessage();
                        Message.From = new MailAddress("hotlogist@monetka.ru");
                        Message.To.Add(new MailAddress(eee));
                        Message.IsBodyHtml = true;
                        Message.Subject = mail_head;
                        Message.Body = mail_body;
                        Smtp.Send(Message);//отправка
                    }
                }

                #endregion
                // Закрываем ТТ. 


                values = new Dictionary<string, object>();
                values["tt_id"] = id;
                ret = wms_get_spfunction_value2("TRANSPORT_PLN.set_mail_sended", values, OracleType.Int32, 0);


            }
            // Если так, то 
        }


