        private void списокОтгруженныхПаллетЗаПериодToolStripMenuItem_Click(object sender, EventArgs e)
        {
            DateTime dt1_min = БИЛЛИНГ_ОТ_время.Value;
            DateTime dt2_min = БИЛЛИНГ_ДО_время.Value;
            string ware_id = this.wms_user.ware_id.ToString();

            if (m_выбранный_склад.Text != "")
            {
                try { ware_id = m_выбранный_склад.Text; }
                catch { }
            }

            if (ware_id == "") { ware_id = "" + this.wms_user.ware_id.ToString() + ""; }

            DateTime dt1 = БИЛЛИНГ_ОТ.Value;
            DateTime dt2 = dt1.AddDays(1);
            if (checkBox4.Checked)
            {
                dt2 = БИЛЛИНГ_ДО.Value;
            }

            string strSQL2 = "select * " +
                            "    from  rrl_sborka_pallets pts " +
                            "    where  "+
                            "    pts.create_date >= " + datetime2sql_ora(dt1, dt1_min) + " " +
                            "    and pts.create_date <= " + datetime2sql_ora(dt2, dt2_min) + " " +
                            "    and ware_id in ( " + ware_id + " ) " +
                            "       ";

            object[] o = ShowQuery(strSQL2, "Список отгруженных паллет", new Point(1, 1), "");

        }

